import { Component, ErrorInfo, ReactNode } from 'react'
import { useLocation } from 'react-router-dom'
import ErrorBoundary from '@/components/ErrorBoundary'

interface Props {
  children: ReactNode
}

function PhonePageName({ pathname }: { pathname: string }) {
  const pageName = pathname.split('/').filter(Boolean).pop() || 'Home'
  return (
    <span className="text-slate-400">
      {pageName}
    </span>
  )
}

export default function PhoneErrorBoundary({ children }: Props) {
  const location = useLocation()

  return (
    <ErrorBoundary
      fallback={
        <div className="min-h-screen w-full bg-[#07020F] text-white flex flex-col items-center justify-center p-4">
          <div className="max-w-lg w-full bg-slate-900/90 border border-red-500/30 rounded-2xl p-6 shadow-2xl">
            <div className="flex items-start gap-4 mb-4">
              <div className="w-12 h-12 bg-red-500/20 rounded-xl flex items-center justify-center shrink-0">
                <svg className="w-6 h-6 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                </svg>
              </div>
              <div className="flex-1">
                <h1 className="text-xl font-bold text-white mb-1">Page Error</h1>
                <p className="text-red-400 font-mono text-sm break-all">
                  <PhonePageName pathname={location.pathname} />
                </p>
              </div>
            </div>
            <p className="text-slate-400 text-sm mb-4">
              Something went wrong while loading this page. Please try refreshing.
            </p>
            <button
              onClick={() => window.location.reload()}
              className="px-5 py-2.5 rounded-xl bg-gradient-to-r from-yellow-500 to-orange-500 hover:from-yellow-400 hover:to-orange-400 text-black font-semibold transition-all"
            >
              🔄 Refresh Page
            </button>
          </div>
        </div>
      }
    >
      {children}
    </ErrorBoundary>
  )
}

import React, { useState, useEffect, useCallback } from 'react'
import { Bell, MessageCircle, User, ChevronDown, X } from 'lucide-react'
import GlobalTicker from '@/components/header/GlobalTicker'
import PhoneDrawer from './PhoneDrawer'
import { useAuthStore } from '@/lib/store'
import { supabase } from '@/lib/supabase'
import { cn } from '@/lib/utils'

interface PhoneHeaderProps {
  title?: string
  showActions?: boolean
  showTickerLinks?: boolean
}

interface Notification {
  id: string
  type: string
  title: string
  message: string
  created_at: string
  is_read: boolean
  metadata?: Record<string, any>
}

export default function PhoneHeader({
  title = 'MAiTROLL.com',
  showActions = true,
  showTickerLinks = true,
}: PhoneHeaderProps) {
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const [notifications, setNotifications] = useState<Notification[]>([])
  const [unreadCount, setUnreadCount] = useState(0)
  const [loading, setLoading] = useState(true)
  const { profile } = useAuthStore()

  const fetchNotifications = useCallback(async () => {
    if (!profile?.id) {
      setNotifications([])
      setUnreadCount(0)
      setLoading(false)
      return
    }

    try {
      const { data, error } = await supabase
        .from('notifications')
        .select('id, type, title, message, created_at, is_read, metadata')
        .eq('user_id', profile.id)
        .order('created_at', { ascending: false })
        .limit(50)

      if (error) throw error

      const notifs = data || []
      setNotifications(notifs)
      setUnreadCount(notifs.filter(n => !n.is_read).length)
    } catch (error) {
      console.error('Failed to load notifications:', error)
    } finally {
      setLoading(false)
    }
  }, [profile?.id])

  useEffect(() => {
    fetchNotifications()

    if (!profile?.id) return

    const channel = supabase
      .channel(`phone-notifications:${profile.id}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'notifications',
          filter: `user_id=eq.${profile.id}`,
        },
        () => fetchNotifications()
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'notifications',
          filter: `user_id=eq.${profile.id}`,
        },
        () => fetchNotifications()
      )
      .subscribe()

    return () => {
      supabase.removeChannel(channel)
    }
  }, [profile?.id, fetchNotifications])

  const handleNotificationClick = async (notification: Notification) => {
    if (!notification.is_read) {
      try {
        await supabase.from('notifications').update({ is_read: true }).eq('id', notification.id)
        setNotifications(prev => prev.map(n => n.id === notification.id ? { ...n, is_read: true } : n))
        setUnreadCount(prev => Math.max(0, prev - 1))
      } catch (error) {
        console.error('Failed to mark as read:', error)
      }
    }

    const metadata = notification.metadata || {}
    let route = '/notifications'

    // Determine route based on notification type
    if (notification.type === 'stream_live' || notification.type === 'broadcast_live' || 
        notification.type === 'user_live' || notification.type === 'followed_user_live') {
      const streamId = metadata.stream_id || metadata.broadcast_id
      if (streamId) route = `/watch/${streamId}`
    } else if (notification.type === 'new_follower' || notification.type === 'someone_followed') {
      const username = metadata.follower_username || metadata.username
      if (username) route = `/profile/${encodeURIComponent(username)}`
    } else if (notification.type === 'message' || notification.type === 'message_received' || 
               notification.type === 'tromail_message') {
      route = '/utromail'
    } else if (notification.type === 'gift_received' || notification.type === 'coin_received') {
      route = '/wallet'
    } else if (metadata.route) {
      route = metadata.route
    }

    setNotificationsOpen(false)
    window.location.assign(route)
  }

  return (
    <>
      <PhoneDrawer
        open={drawerOpen}
        onClose={() => setDrawerOpen(false)}
      />

      <header className="sticky top-0 z-50 border-b border-[#00BFFF]/20 bg-[#03030a]/90 backdrop-blur-2xl">
        <div className="flex items-center justify-between px-4 py-3">

          {/* Menu */}
          <button
            type="button"
            aria-label="Open menu"
            onClick={() => setDrawerOpen(true)}
            className="flex h-10 w-10 items-center justify-center rounded-xl border border-white/10 bg-white/[0.04] text-white transition active:scale-95"
          >
            <span className="text-xl leading-none">☰</span>
          </button>

          {/* Brand */}
          <div className="min-w-0 flex-1 px-3 text-center">
            <h1 className="truncate bg-gradient-to-r from-[#00BFFF] via-white to-[#BF00FF] bg-clip-text text-lg font-black tracking-tight text-transparent">
              {title}
            </h1>

            <div className="mt-0.5 flex items-center justify-center gap-1.5">
              <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-[#00BFFF] shadow-[0_0_8px_#00BFFF]" />
              <span className="text-[9px] font-bold uppercase tracking-[0.2em] text-zinc-500">
                Live Network
              </span>
            </div>
          </div>

          {/* Actions */}
          {showActions ? (
            <div className="flex shrink-0 items-center gap-2">

              {/* Notifications */}
              <div className="relative">
                <button
                  type="button"
                  aria-label={`Notifications${unreadCount > 0 ? `, ${unreadCount} unread` : ''}`}
                  onClick={() => setNotificationsOpen(!notificationsOpen)}
                  className="relative flex h-12 w-12 items-center justify-center rounded-xl border border-white/15 bg-white/[0.08] text-white transition active:scale-90"
                >
                  <Bell size={28} strokeWidth={2.5} className="text-white drop-shadow-[0_0_8px_rgba(255,255,255,0.6)]" />
                </button>

                {/* Notifications Dropdown */}
                {notificationsOpen && (
                  <div className="absolute right-0 top-full mt-2 w-[320px] max-h-[500px] overflow-y-auto rounded-2xl border border-white/10 bg-[#050715]/95 backdrop-blur-2xl shadow-2xl z-50 animate-in slide-in-from-top-2 duration-200">
                    <div className="flex items-center justify-between px-4 py-3 border-b border-white/10">
                      <h3 className="font-bold text-white">Notifications</h3>
                      {unreadCount > 0 && (
                        <button
                          onClick={async () => {
                            try {
                              await supabase.from('notifications').update({ is_read: true }).eq('user_id', profile?.id)
                              setNotifications(prev => prev.map(n => ({ ...n, is_read: true })))
                              setUnreadCount(0)
                            } catch (e) { console.error(e) }
                          }}
                          className="text-xs text-cyan-400 font-medium"
                        >
                          Mark all read
                        </button>
                      )}
                    </div>

                    {loading ? (
                      <div className="flex items-center justify-center py-8 text-slate-500">
                        <div className="h-6 w-6 animate-spin rounded-full border-2 border-cyan-400/30 border-t-cyan-400" />
                      </div>
                    ) : notifications.length === 0 ? (
                      <div className="px-4 py-8 text-center text-slate-500">
                        <Bell className="h-10 w-10 mx-auto mb-2 text-slate-600" />
                        <p>No notifications yet</p>
                      </div>
                    ) : (
                      <div className="divide-y divide-white/5">
                        {notifications.map(notification => (
                          <button
                            key={notification.id}
                            onClick={() => handleNotificationClick(notification)}
                            className={cn(
                              'w-full px-4 py-3 text-left transition',
                              !notification.is_read
                                ? 'bg-cyan-400/5 hover:bg-cyan-400/10'
                                : 'hover:bg-white/5'
                            )}
                          >
                            <div className="flex items-start gap-3">
                              <div className={cn(
                                'flex h-8 w-8 shrink-0 items-center justify-center rounded-xl',
                                !notification.is_read
                                  ? 'bg-cyan-400/15 border border-cyan-400/20'
                                  : 'bg-white/5 border border-white/10'
                              )}>
                                <Bell className={cn('h-4 w-4', !notification.is_read ? 'text-cyan-300' : 'text-slate-500')} />
                              </div>
                              <div className="flex-1 min-w-0">
                                <p className={cn('font-medium truncate', !notification.is_read ? 'text-white' : 'text-slate-300')}>
                                  {notification.title}
                                </p>
                                <p className="mt-0.5 text-xs text-slate-500 line-clamp-1">
                                  {notification.message}
                                </p>
                                <p className="mt-1 text-[10px] text-slate-600">
                                  {new Date(notification.created_at).toLocaleString()}
                                </p>
                              </div>
                              {!notification.is_read && (
                                <div className="h-2 w-2 rounded-full bg-cyan-400 shrink-0 mt-2" />
                              )}
                            </div>
                          </button>
                        ))}
                      </div>
                    )}

                    <div className="px-4 py-2 border-t border-white/10">
                      <button
                        onClick={() => { setNotificationsOpen(false); window.location.assign('/notifications') }}
                        className="w-full text-center text-sm text-cyan-400 font-medium"
                      >
                        View all notifications
                      </button>
                    </div>
                  </div>
                )}
              </div>

              {/* Profile */}
              <div className="relative">
                <button
                  type="button"
                  aria-label="Profile"
                  onClick={() => window.location.assign('/profile')}
className="flex h-12 w-12 items-center justify-center rounded-xl border border-white/15 bg-white/[0.08] text-white transition active:scale-90"
                  >
                    {profile?.avatar_url ? (
                      <img
                        src={profile.avatar_url}
                        alt={profile.username}
                        className="h-12 w-12 rounded-xl object-cover"
                      />
                    ) : (
                      <User size={28} strokeWidth={2.5} className="text-white drop-shadow-[0_0_8px_rgba(255,255,255,0.6)]" />
                  )}
                </button>
              </div>

            </div>
          ) : (
            <div className="h-10 w-10" />
          )}
        </div>

        {/* Global activity ticker */}
        <div className="border-t border-white/5 px-3 py-1.5">
          <GlobalTicker showSeoLinks={showTickerLinks} />
        </div>
      </header>
    </>
  )
}

/**
 * MAI PIKS — FULL SCREEN STORY VIEWER
 *
 *  - photos advance automatically after 5s, videos advance when they finish
 *  - tap / swipe left and right to scroll through a story
 *  - reaching the end of one user's story rolls straight into the next user
 *    they follow, and running off the last story closes the viewer
 *  - owners can hard delete any piece of their own story
 *  - viewers can tip troll coins (80% owner / 20% platform fee pool)
 */

import React, { useCallback, useEffect, useRef, useState } from 'react'
import { ChevronLeft, ChevronRight, Coins, ShieldCheck, Sparkles, Trash2, X } from 'lucide-react'

import { supabase } from '../../lib/supabase'
import {
  ExpiryCountdown,
  MaiPiksAvatar,
  PHOTO_STORY_DURATION_MS,
  TIP_PLATFORM_FEE_PERCENT,
  TIP_PRESETS,
  type MaiPiksUser,
  type PiksStory,
  type PiksStoryItem,
} from './maiPiksShared'

/* ========================================================================= */
/* STORY VIEWER                                                              */
/* ========================================================================= */

interface StoryViewerProps {
  stories: PiksStory[]
  startIndex: number
  currentUser: MaiPiksUser | null
  onClose: () => void
  onDeleteItem: (item: PiksStoryItem) => Promise<boolean>
  onTip: (story: PiksStory, item: PiksStoryItem | null, amount: number) => Promise<boolean>
  onScreenshot: (payload: {
    contentType: 'story' | 'feed' | 'profile' | 'chat' | 'broadcast'
    contentId?: string
    ownerUserId?: string
  }) => void
}

/**
 * Full screen MAI Piks story viewer.
 */
export default function StoryViewer({
  stories,
  startIndex,
  currentUser,
  onClose,
  onDeleteItem,
  onTip,
  onScreenshot,
}: StoryViewerProps) {
  const [storyIndex, setStoryIndex] = useState(startIndex)
  const [itemIndex, setItemIndex] = useState(0)
  const [progress, setProgress] = useState(0)
  const [paused, setPaused] = useState(false)
  const [showTipModal, setShowTipModal] = useState(false)
  const [deleting, setDeleting] = useState(false)

  const videoRef = useRef<HTMLVideoElement | null>(null)
  const rafRef = useRef<number | null>(null)
  const startedAtRef = useRef<number>(0)
  const elapsedRef = useRef<number>(0)
  const pointerStartRef = useRef<{ x: number; y: number; time: number; type: string } | null>(null)
  const viewedRef = useRef<Set<string>>(new Set())

  const story = stories[storyIndex]
  const item = story?.items[itemIndex]

  const isOwn = Boolean(story?.isOwn)
  const canTip = Boolean(currentUser && story && !isOwn)

  /* ------------------------------------------------------------------ */
  /* Navigation                                                        */
  /* ------------------------------------------------------------------ */

  const resetTimer = useCallback(() => {
    elapsedRef.current = 0
    startedAtRef.current = performance.now()
    setProgress(0)
  }, [])

  /** Next piece of media, rolling into the next user's story at the end. */
  const goNext = useCallback(() => {
    if (!story) return

    if (itemIndex < story.items.length - 1) {
      setItemIndex((value) => value + 1)
      resetTimer()
      return
    }

    if (storyIndex < stories.length - 1) {
      setStoryIndex((value) => value + 1)
      setItemIndex(0)
      resetTimer()
      return
    }

    onClose()
  }, [story, itemIndex, storyIndex, stories.length, resetTimer, onClose])

  /** Previous piece of media, rolling back into the previous user's story. */
  const goPrev = useCallback(() => {
    if (itemIndex > 0) {
      setItemIndex((value) => value - 1)
      resetTimer()
      return
    }

    if (storyIndex > 0) {
      const prevIndex = storyIndex - 1
      setStoryIndex(prevIndex)
      setItemIndex(Math.max((stories[prevIndex]?.items.length ?? 1) - 1, 0))
      resetTimer()
      return
    }

    resetTimer()
  }, [itemIndex, storyIndex, stories, resetTimer])

  /* Keep indexes valid if media is deleted underneath us. */
  useEffect(() => {
    if (!stories.length) {
      onClose()
      return
    }

    if (storyIndex > stories.length - 1) {
      setStoryIndex(stories.length - 1)
      setItemIndex(0)
      return
    }

    const activeStory = stories[storyIndex]
    if (activeStory && itemIndex > activeStory.items.length - 1) {
      setItemIndex(Math.max(activeStory.items.length - 1, 0))
    }
  }, [stories, storyIndex, itemIndex, onClose])

  /* ------------------------------------------------------------------ */
  /* Auto advance                                                      */
  /* ------------------------------------------------------------------ */

  useEffect(() => {
    resetTimer()
  }, [item?.id, resetTimer])

  useEffect(() => {
    if (!item) return

    /* The tip sheet freezes the story so nobody loses their place. */
    const frozen = paused || showTipModal || deleting

    const cancelRaf = () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current)
        rafRef.current = null
      }
    }

    /*
     * Videos drive their own progress from `timeupdate` and advance on `ended`,
     * so only photos need the 5 second timer.
     */
    if (item.mediaType === 'video') {
      cancelRaf()
      if (frozen) videoRef.current?.pause()
      else void videoRef.current?.play().catch(() => undefined)
      return
    }

    if (frozen) {
      cancelRaf()
      return
    }

    startedAtRef.current = performance.now() - elapsedRef.current

    const step = () => {
      const elapsed = performance.now() - startedAtRef.current
      elapsedRef.current = elapsed

      const ratio = Math.min(elapsed / PHOTO_STORY_DURATION_MS, 1)
      setProgress(ratio)

      if (ratio >= 1) {
        rafRef.current = null
        goNext()
        return
      }

      rafRef.current = requestAnimationFrame(step)
    }

    rafRef.current = requestAnimationFrame(step)

    return cancelRaf
  }, [item, paused, showTipModal, deleting, goNext])

  /* ------------------------------------------------------------------ */
  /* View tracking + screenshot notice                                 */
  /* ------------------------------------------------------------------ */

  useEffect(() => {
    if (!item || !currentUser || isOwn) return
    if (viewedRef.current.has(item.id)) return

    viewedRef.current.add(item.id)

    void (async () => {
      try {
        await supabase.rpc('maipiks_record_story_view', { p_item_id: item.id })
      } catch {
        /* View tracking is best effort. */
      }
    })()

    if (!currentUser.screenshotsAllowed) {
      onScreenshot({ contentType: 'story', contentId: item.id, ownerUserId: story?.userId })
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [item?.id, currentUser?.id, isOwn])

  /* ------------------------------------------------------------------ */
  /* Keyboard                                                          */
  /* ------------------------------------------------------------------ */

  useEffect(() => {
    const handleKey = (event: KeyboardEvent) => {
      if (event.key === 'ArrowRight') goNext()
      else if (event.key === 'ArrowLeft') goPrev()
      else if (event.key === 'Escape') onClose()
    }

    window.addEventListener('keydown', handleKey)
    return () => window.removeEventListener('keydown', handleKey)
  }, [goNext, goPrev, onClose])

  /* ------------------------------------------------------------------ */
  /* Pointer: tap zones, swipe and press-to-pause                      */
  /* ------------------------------------------------------------------ */

  /*
   * Pointer events cover mouse, touch and pen with one code path, which avoids
   * the classic double-advance from a touchend plus a synthesised click.
   */
  const handlePointerDown = (event: React.PointerEvent) => {
    pointerStartRef.current = {
      x: event.clientX,
      y: event.clientY,
      time: Date.now(),
      type: event.pointerType,
    }
    setPaused(true)
  }

  const handlePointerUp = (event: React.PointerEvent) => {
    setPaused(false)

    const start = pointerStartRef.current
    pointerStartRef.current = null
    if (!start) return

    const dx = event.clientX - start.x
    const dy = event.clientY - start.y
    const heldFor = Date.now() - start.time

    /* Swipe down closes, like every other story viewer. */
    if (start.type !== 'mouse' && dy > 90 && Math.abs(dy) > Math.abs(dx)) {
      onClose()
      return
    }

    /* Horizontal swipe scrolls between story media and between users. */
    if (Math.abs(dx) > 55 && Math.abs(dx) > Math.abs(dy)) {
      if (dx < 0) goNext()
      else goPrev()
      return
    }

    /* A long press was a deliberate pause, not a tap. */
    if (heldFor > 350) return

    /* Tap: right third forward, left third back. */
    const width = window.innerWidth || 1
    if (event.clientX > width * 0.66) goNext()
    else if (event.clientX < width * 0.34) goPrev()
  }

  const handleDelete = async () => {
    if (!item || !isOwn) return
    if (!window.confirm('Delete this from your story?')) return

    setDeleting(true)
    const removed = await onDeleteItem(item)
    setDeleting(false)

    if (!removed) return

    /* If that was the last piece of media, move on. */
    if ((story?.items.length ?? 0) <= 1) {
      if (stories.length <= 1) onClose()
      else goNext()
      return
    }

    setItemIndex((value) => Math.max(Math.min(value, (story?.items.length ?? 1) - 2), 0))
    resetTimer()
  }

  if (!story || !item) return null

  return (
    <div className="fixed inset-0 z-[200] select-none bg-black">
      {/* MEDIA */}
      <div className="absolute inset-0 flex items-center justify-center">
        {item.mediaType === 'video' ? (
          <video
            ref={videoRef}
            key={item.id}
            src={item.mediaUrl}
            className="max-h-full max-w-full object-contain"
            autoPlay
            playsInline
            onEnded={goNext}
            onLoadedMetadata={() => {
              startedAtRef.current = performance.now()
              elapsedRef.current = 0
            }}
            onTimeUpdate={(event) => {
              const el = event.currentTarget
              if (Number.isFinite(el.duration) && el.duration > 0) {
                setProgress(Math.min(el.currentTime / el.duration, 1))
              }
            }}
          />
        ) : (
          <img src={item.mediaUrl} alt="" className="max-h-full max-w-full object-contain" />
        )}
      </div>

      {/*
        Single transparent gesture layer: tap the left/right third to scroll,
        swipe horizontally to move between stories, swipe down to close and
        press and hold to pause. Header and footer controls sit above it.
      */}
      <div
        className="absolute bottom-20 left-0 right-0 top-16 z-10"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerUp={handlePointerUp}
        onPointerCancel={() => {
          pointerStartRef.current = null
          setPaused(false)
        }}
      />

      {/* TOP GRADIENT */}
      <div className="pointer-events-none absolute left-0 right-0 top-0 z-20 h-36 bg-gradient-to-b from-black/85 to-transparent" />
      <div className="pointer-events-none absolute bottom-0 left-0 right-0 z-20 h-40 bg-gradient-to-t from-black/85 to-transparent" />

      {/* PROGRESS BARS — one segment per piece of media in the story */}
      <div className="absolute left-3 right-3 top-3 z-30 flex gap-1">
        {story.items.map((storyItem, index) => (
          <div key={storyItem.id} className="h-[2.5px] flex-1 overflow-hidden rounded-full bg-white/25">
            <div
              className="h-full rounded-full bg-white transition-[width] duration-100 ease-linear"
              style={{
                width:
                  index < itemIndex
                    ? '100%'
                    : index === itemIndex
                      ? `${Math.round(progress * 100)}%`
                      : '0%',
              }}
            />
          </div>
        ))}
      </div>

      {/* HEADER */}
      <div className="absolute left-4 right-4 top-8 z-30 flex items-start justify-between gap-3">
        <div className="flex min-w-0 items-center gap-2">
          <MaiPiksAvatar src={story.avatarUrl} purple />
          <div className="min-w-0">
            <p className="truncate text-xs font-black">
              {isOwn ? 'Your Story' : `@${story.username}`}
            </p>
            <div className="mt-0.5 flex items-center gap-1.5">
