        <div className="absolute bottom-[104px] left-4 right-4 z-30">
          <p className="rounded-2xl border border-white/10 bg-black/55 px-4 py-2.5 text-xs leading-relaxed text-zinc-100 backdrop-blur-xl">
            {item.caption}
