function getRarity(gift: GiftItem): Rarity {
  const rarity = String(gift.rarity || '').toLowerCase()

  if (
    rarity === 'common' ||
    rarity === 'uncommon' ||
    rarity === 'rare' ||
    rarity === 'epic' ||
    rarity === 'legendary' ||
    rarity === 'mythic'
  ) {
    return rarity
  }

  return 'common'
}

export default function PhoneGiftModal({
  isOpen,
  onClose,
  recipientId,
  streamId,
  broadcasterId = recipientId,
  activeUserIds = [],
  userProfiles = {},
  onGiftSent,
  sharedChannel,
}: PhoneGiftModalProps) {
  const { user, profile } = useAuthStore()
  const { sendGift, isSending } = useGiftSystem()

  const [gifts, setGifts] = useState<GiftItem[]>([])
  const [selectedCategory, setSelectedCategory] =
    useState<GiftCategory>('all')
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedGift, setSelectedGift] = useState<GiftItem | null>(null)
  const [quantity, setQuantity] = useState(1)
  const [isLoading, setIsLoading] = useState(true)
  const [showMKey, setShowMKey] = useState(false)

  const [giftTarget, setGiftTarget] = useState<GiftTarget>({
    type: 'specific',
    userId: recipientId,
  })

  const { wallet: mkeyWallet } = useMKeyWallet({
    enabled: isOpen,
  })

  useEffect(() => {
    if (!isOpen) return

    setGiftTarget({
      type: 'specific',
      userId: recipientId,
    })

    setSelectedGift(null)
    setQuantity(1)
    setSearchQuery('')
    setSelectedCategory('all')
    setShowMKey(false)
  }, [isOpen, recipientId])

  useEffect(() => {
    if (!isOpen) return

    setIsLoading(true)
    setGifts([])
    fetchGifts()
  }, [isOpen])

  async function fetchGifts() {
    try {
      const tables = ['gift_items']

      let rawGifts: any[] = []

      for (const table of tables) {
        try {
          const { data, error } = await supabase
            .from(table)
            .select('*')
            .order('coin_cost', { ascending: true })
            .limit(200)

          if (!error && data && data.length > 0) {
            rawGifts = data
            break
          }
        } catch {
          continue
        }
      }

      if (rawGifts.length === 0) {
        const { data: purchasableItems } = await supabase
          .from('purchasable_items')
          .select('*')
          .eq('category', 'gift')
          .eq('is_active', true)
          .order('coin_price', { ascending: true })
          .limit(200)

        if (purchasableItems && purchasableItems.length > 0) {
          rawGifts = purchasableItems
        }
      }

      const transformedGifts: GiftItem[] = rawGifts.map((g: any) => {
        const id =
          g.id ||
          String(g._id || g.gift_id || '')

        const name =
          g.name ||
          g.gift_name ||
          g.title ||
          g.display_name ||
          'Unknown Gift'

        const icon =
          g.icon ||
          g.icon_url ||
          g.emoji ||
          g.gift_icon ||
          '🎁'

        const coinCost = Number(
          g.coin_cost ??
            g.coinCost ??
            g.value ??
            g.cost ??
            g.price ??
            g.coin_price ??
            g.coins ??
            g.amount ??
            0
        )

        const slug =
          g.slug ||
          g.gift_slug ||
          g.item_key ||
          name.toLowerCase().replace(/\s+/g, '-')

        const animationType =
          g.animation_type ||
          g.animationType ||
          g.animation ||
          undefined

        const category =
          g.category ||
          g.gift_category ||
          g.metadata?.subcategory ||
          undefined

        return {
          id,
          name,
          icon,
          coinCost,
          type: coinCost > 0 ? 'paid' : 'free',
          slug,
          animationKey:
            g.animation_key ||
            g.animationKey ||
            g.gift_slug ||
            slug,
          animationType,
          animationUrl:
            g.animation_url ||
            g.animationUrl ||
            g.video_url ||
            g.videoUrl ||
            null,
          videoUrl:
            g.video_url ||
            g.videoUrl ||
            g.animation_url ||
            g.animationUrl ||
            null,
          animationDurationMs:
            g.animation_duration_ms ||
            g.animationDurationMs ||
            undefined,
          soundUrl:
            g.sound_url ||
            g.soundUrl ||
            null,
          isFullscreen:
            g.is_fullscreen ??
            g.isFullscreen ??
            undefined,
          rarity: g.rarity || undefined,
          description:
            g.description ||
            undefined,
          trayVisualUrl:
            g.tray_visual_url ||
            g.trayVisualUrl ||
            undefined,
          trayGradient:
            g.tray_gradient ||
            g.trayGradient ||
            undefined,
          category,
        }
      })

      setGifts(transformedGifts)
    } catch (err) {
      console.error(
        '[PhoneGiftModal] Failed to load gifts:',
        err
      )
    } finally {
      setIsLoading(false)
    }
  }

  const getGiftCategory = (
    gift: GiftItem
  ): GiftCategory => {
    const nameLower = gift.name.toLowerCase()
    const icon = gift.icon
    const category = String(
      gift.category || ''
    ).toLowerCase()

    if (
      category.includes('royalty') ||
      category.includes('luxury') ||
      nameLower.includes('crown') ||
      nameLower.includes('diamond') ||
      nameLower.includes('gold') ||
      nameLower.includes('platinum') ||
      nameLower.includes('aurora')
    ) {
      return 'luxury'
    }

    if (
      nameLower.includes('car') ||
      nameLower.includes('lamborghini') ||
      nameLower.includes('ferrari')
    ) {
      return 'cars'
    }

    if (
      nameLower.includes('house') ||
      nameLower.includes('mansion') ||
      nameLower.includes('castle')
    ) {
      return 'houses'
    }

    if (
      nameLower.includes('boat') ||
      nameLower.includes('yacht')
    ) {
      return 'boats'
    }

    if (
      nameLower.includes('plane') ||
      nameLower.includes('jet') ||
      nameLower.includes('helicopter')
    ) {
      return 'planes'
    }

    if (
      nameLower.includes('cigarette') ||
      nameLower.includes('cigar') ||
      nameLower.includes('smoke')
    ) {
      return 'smoking'
    }

    if (
      nameLower.includes('beer') ||
      nameLower.includes('wine') ||
      nameLower.includes('champagne')
    ) {
      return 'drinking'
    }

    if (
      nameLower.includes('clown') ||
      nameLower.includes('meme') ||
      nameLower.includes('troll')
    ) {
      return 'funny'
    }

    if (
      nameLower.includes('christmas') ||
      nameLower.includes('santa') ||
      nameLower.includes('pumpkin')
    ) {
      return 'holiday'
    }

    if (
      nameLower.includes('rainbow') ||
      nameLower.includes('pride')
    ) {
      return 'lgbt'
    }

    if (
      icon === '👨' ||
      nameLower.includes('men') ||
      nameLower.includes('muscle')
    ) {
      return 'men'
    }

    if (
      icon === '👩' ||
      nameLower.includes('women') ||
      nameLower.includes('dress')
    ) {
      return 'women'
    }

    if (
      nameLower.includes('sunny') ||
      nameLower.includes('snow') ||
      nameLower.includes('spring')
    ) {
      return 'seasonal'
    }

    return 'general'
  }

  const filteredGifts = useMemo(() => {
    let filtered = gifts

    if (selectedCategory !== 'all') {
      filtered = filtered.filter(
        gift =>
          getGiftCategory(gift) ===
          selectedCategory
      )
    }

    if (searchQuery.trim()) {
      const query =
        searchQuery.toLowerCase()

      filtered = filtered.filter(gift =>
        gift.name
          .toLowerCase()
          .includes(query)
      )
    }

    return filtered
  }, [
    gifts,
    selectedCategory,
    searchQuery,
  ])

  const totalCost = selectedGift
    ? selectedGift.coinCost * quantity
    : 0

  const handleSendGift = async () => {
    if (
      !selectedGift ||
      !user ||
      !profile ||
      isSending
    ) {
      return
    }

    const targetReceiverId =
      giftTarget.userId || recipientId

    if (user.id === targetReceiverId) {
      toast.error(
        'You cannot send gifts to yourself'
      )
      return
    }

    try {
      const result = await sendGift(
        selectedGift,
        {
          receiverId: targetReceiverId,
          quantity,
          streamId,
        }
      )

      if (
        result &&
        typeof result === 'object' &&
        result.success
      ) {
        toast.success(
          `Sent ${selectedGift.name} x${quantity}`
        )

        const sentGift = selectedGift

        setSelectedGift(null)
        setQuantity(1)

        onGiftSent?.(
          sentGift,
          {
            type: 'specific',
            userId: targetReceiverId,
            quantity,
          }
        )
      }
    } catch {
      toast.error(
        'Failed to send gift'
      )
    }
  }

  if (!isOpen) return null

  return (
    <div
      className="fixed inset-0 z-[100] flex items-end bg-black/70 backdrop-blur-[2px]"
      onClick={onClose}
