  const roleAccess = usePhoneRoleAccess()

  const initialQuery = searchParams.get('q') || ''
  const [search, setSearch] = useState(initialQuery)
  const [broadcasts, setBroadcasts] = useState<Broadcast[]>([])
  const [posts, setPosts] = useState<WallPost[]>([])
  const [users, setUsers] = useState<{ id: string; username: string; display_name?: string; avatar_url?: string }[]>([])
  const [loadingStreams, setLoadingStreams] = useState(true)
  const [loadingPosts, setLoadingPosts] = useState(true)
  const [loadingUsers, setLoadingUsers] = useState(false)

  const sections: PhoneNavSection[] = useMemo(
    () => getPhoneNavSections(roleAccess),
    [roleAccess],
  )

  const visibleSections = useMemo(
    () =>
      sections.filter((section) =>
        section.items.some((item) => item.show !== false),
      ),
    [sections],
  )

  const flatPages = useMemo(
    () =>
      visibleSections.flatMap((section) =>
        section.items
          .filter((item) => item.show !== false)
          .map((item) => ({ ...item, section: section.title })),
      ),
    [visibleSections],
  )

  const filteredPages = useMemo(() => {
    if (!search.trim()) return flatPages
    const q = search.trim().toLowerCase()
    return flatPages.filter((item) =>
      item.label.toLowerCase().includes(q),
    )
  }, [flatPages, search])

  const fetchStreams = useCallback(async () => {
    try {
      setLoadingStreams(true)
      const { data, error } = await supabase
        .from('streams')
        .select(
          `
            id,
            title,
            category,
            current_viewers,
            viewer_count,
            is_live,
            is_featured,
            broadcaster_id,
            battle_mode,
            battle_format
          `,
          { count: 'exact' },
        )
        .eq('is_live', true)
        .order('current_viewers', { ascending: false })
        .limit(12)

      if (error) throw error

      const streamsWithBroadcasters: any[] = []
      if (data && data.length > 0) {
        const broadcasterIds = Array.from(
          new Set(
            data
              .map((stream: any) => stream.broadcaster_id)
              .filter(Boolean),
          ),
        )

        let broadcasterMap = new Map<string, any>()
        if (broadcasterIds.length > 0) {
          const { data: broadcasters } = await supabase
            .from('user_profiles')
            .select('id, username, avatar_url, level, created_at')
            .in('id', broadcasterIds)

          if (broadcasters) {
            broadcasterMap = new Map(
              broadcasters.map((b: any) => [b.id, b]),
            )
          }
        }

        streamsWithBroadcasters.push(
          ...data.map((stream: any) => ({
            ...stream,
            user_profiles: broadcasterMap.get(stream.broadcaster_id),
            type: 'stream',
          })),
        )
      }

      setBroadcasts(streamsWithBroadcasters)
    } catch (err) {
      console.error('Failed to fetch explore streams:', err)
    } finally {
      setLoadingStreams(false)
    }
  }, [])

  const fetchPosts = useCallback(async () => {
    try {
      setLoadingPosts(true)
      const { data, error } = await supabase
        .from('troll_wall_posts')
        .select(
          'id, content, created_at, user_id, username, avatar_url, likes_count, replies_count',
        )
        .is('reply_to_post_id', null)
        .order('created_at', { ascending: false })
        .limit(20)

      if (error) throw error
      setPosts((data || []) as WallPost[])
    } catch (err) {
      console.error('Failed to fetch explore posts:', err)
    } finally {
      setLoadingPosts(false)
    }
  }, [])

  useEffect(() => {
    fetchStreams()
    fetchPosts()
  }, [fetchStreams, fetchPosts])

  useEffect(() => {
    const query = search.trim()
    if (!query) {
      setUsers([])
      return
    }

    let cancelled = false
    setLoadingUsers(true)

    const isUserQuery = query.startsWith('@') || query.length >= 2

    if (isUserQuery) {
      const term = query.startsWith('@') ? query.slice(1) : query
      searchUsers(term)
        .then((results) => {
          if (!cancelled) {
            setUsers(
              results.map((u: any) => ({
                id: u.id,
                username: u.username,
                display_name: u.display_name,
                avatar_url: u.avatar_url,
              })),
            )
          }
        })
        .catch((err) => {
          console.error('Failed to search users:', err)
        })
        .finally(() => {
          if (!cancelled) setLoadingUsers(false)
        })
    } else {
      setLoadingUsers(false)
      setUsers([])
    }

    return () => {
      cancelled = true
    }
  }, [search])

  const getTimeSince = (timestamp: string) => {
    const minutes = Math.floor(
      (Date.now() - new Date(timestamp).getTime()) / 60000,
    )
    if (minutes < 60) return `${minutes}m`
    const hours = Math.floor(minutes / 60)
    if (hours < 24) return `${hours}h`
    const days = Math.floor(hours / 24)
    return `${days}d`
  }

  const totalViewers = broadcasts.reduce(
    (total, b) => total + (b.current_viewers || b.viewer_count || 0),
    0,
  )

  return (
    <div className="relative min-h-screen w-full overflow-x-hidden bg-[#05010f] text-white">
      <div className="pointer-events-none fixed inset-0 overflow-hidden">
        <div className="absolute left-[-25%] top-[-10%] h-[320px] w-[320px] rounded-full bg-[#8b00ff]/10 blur-[100px]" />
        <div className="absolute right-[-25%] top-[20%] h-[280px] w-[280px] rounded-full bg-[#00BFFF]/10 blur-[100px]" />
        <div className="absolute bottom-[10%] left-[20%] h-[240px] w-[240px] rounded-full bg-purple-600/10 blur-[100px]" />
      </div>

      <header className="sticky top-0 z-50 border-b border-[#00BFFF]/20 bg-[#05010f]/90 px-4 py-3 backdrop-blur-2xl">
        <div className="flex items-center gap-3">
          <button
            type="button"
            aria-label="Go back"
            onClick={() => navigate(-1)}
            className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl border border-white/10 bg-white/5 text-white transition active:scale-95"
          >
            <ArrowLeft size={18} />
          </button>

          <div className="flex-1">
            <div className="relative">
              <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-zinc-500" />
               <input
                 type="text"
                 value={search}
                 onChange={(e) => setSearch(e.target.value)}
                 placeholder="Search pages, users, posts, #tags..."
                 className="w-full rounded-xl border border-white/10 bg-white/5 py-2.5 pl-9 pr-4 text-sm text-white outline-none placeholder:text-zinc-500 focus:border-cyan-400/50 focus:ring-1 focus:ring-cyan-400/20"
               />
            </div>
          </div>
        </div>
      </header>

      <main className="relative z-10 px-4 pb-10 pt-4">
        {!search.trim() && (
          <>
            {/* Live Now */}
            <section className={`${neonCard} overflow-hidden p-4`}>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-[#8b00ff] to-[#00BFFF] shadow-[0_0_20px_rgba(0,191,255,.25)]">
                    <Radio size={16} className="text-white" />
                  </span>
                  <div>
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] text-[#00BFFF]">
                      Broadcast Network
                    </p>
                    <h2 className={`text-lg font-black ${neonTextGradient}`}>
                      Live Now
                    </h2>
                  </div>
                </div>
                <div className="flex items-center gap-1 text-[10px] font-black text-zinc-400">
                  <Eye size={12} />
                  {totalViewers.toLocaleString()}
                </div>
              </div>

              {loadingStreams ? (
                <div className="mt-4 grid grid-cols-2 gap-2">
                  {Array.from({ length: 4 }).map((_, i) => (
                    <div
                      key={i}
                      className="aspect-video rounded-xl bg-white/[0.04] animate-pulse"
                    />
                  ))}
                </div>
              ) : broadcasts.length === 0 ? (
                <p className="mt-4 text-center text-xs text-zinc-500">
                  No one is live right now.
                </p>
              ) : (
                <div className="mt-4 grid grid-cols-2 gap-2">
                  {broadcasts.slice(0, 6).map((broadcast) => (
                    <button
                      key={broadcast.id}
                      onClick={() =>
                        broadcast.is_ended
                          ? navigate(`/replay/id/${broadcast.id}`)
                          : navigate(`/watch/${broadcast.id}`)
                      }
                      className="relative aspect-video overflow-hidden rounded-xl border border-white/10 bg-white/[0.03] text-left transition active:scale-[0.97]"
                    >
                      {broadcast.thumbnail_url ? (
                        <img
                          src={broadcast.thumbnail_url}
                          alt={broadcast.title || 'Live'}
                          className="h-full w-full object-cover"
                        />
                      ) : (
                        <div className="flex h-full w-full items-center justify-center bg-gradient-to-br from-purple-950 via-[#09051b] to-cyan-950">
                          <Play size={20} className="text-white/30" />
                        </div>
                      )}
                      <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/10 to-transparent" />
                      <div className="absolute left-2 top-2 flex items-center gap-1 rounded-md bg-red-600/90 px-1.5 py-1 backdrop-blur-md">
                        {broadcast.is_ended ? (
                          <Play size={8} fill="white" />
                        ) : (
                          <span className="h-1 w-1 animate-pulse rounded-full bg-white" />
                        )}
                        <span className="text-[8px] font-black uppercase tracking-wider text-white">
                          {broadcast.is_ended ? 'Replay' : 'Live'}
                        </span>
                      </div>
                      <div className="absolute bottom-2 left-2 right-2">
                        <p className="truncate text-[10px] font-black text-white">
                          {broadcast.title || 'Untitled Stream'}
                        </p>
                        <p className="truncate text-[8px] font-bold text-zinc-300">
                          {broadcast.user_profiles?.username || 'Unknown'}
                        </p>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </section>

            {/* Trending Posts */}
            <section className="mt-6">
              <div className="flex items-center gap-2 px-1">
                <Flame size={16} className="text-orange-400" />
                <h3 className="text-sm font-black uppercase tracking-[0.2em] text-zinc-300">
                  Trending Posts
                </h3>
              </div>

              {loadingPosts ? (
                <div className="mt-3 space-y-2">
                  {Array.from({ length: 3 }).map((_, i) => (
                    <div
                      key={i}
                      className={`${neonCard} h-20 animate-pulse`}
                    />
                  ))}
                </div>
              ) : posts.length === 0 ? (
                <p className="mt-3 text-center text-xs text-zinc-500">
                  No posts yet. Be the first!
                </p>
              ) : (
                <div className="mt-3 space-y-2">
                  {posts.slice(0, 8).map((post) => (
                    <button
                      key={post.id}
                      onClick={() => navigate('/community-wall')}
                      className={`${neonCard} w-full px-4 py-3 text-left transition active:scale-[0.985]`}
                    >
                      <div className="flex items-center gap-2">
                        <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-[#8b00ff] to-[#00BFFF] text-[10px] font-black text-white">
                          {(post.username || '?').charAt(0).toUpperCase()}
                        </div>
                        <span className="truncate text-xs font-black text-white">
                          {post.username || 'Unknown'}
                        </span>
                        <span className="text-[9px] font-bold text-zinc-500">
                          {getTimeSince(post.created_at)}
                        </span>
                      </div>
                      <p className="mt-1.5 line-clamp-2 text-xs leading-5 text-zinc-300">
                        {post.content}
                      </p>
                    </button>
                  ))}
                </div>
              )}
            </section>

            {/* All Pages */}
            <section className="mt-6">
              <h3 className="px-1 text-sm font-black uppercase tracking-[0.2em] text-zinc-300">
                All Pages
              </h3>
              <div className="mt-3 space-y-4">
                {visibleSections.map((section) => (
                  <div key={section.title}>
                    <p className="mb-2 px-1 text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500">
                      {section.title}
                    </p>
                    <div className="grid grid-cols-3 gap-2">
                      {section.items
                        .filter((item) => item.show !== false)
                        .map((item) => {
                          const ItemIcon = item.icon
                          return (
                            <button
                              key={item.path + item.label}
                              onClick={() => navigate(item.path)}
                              className="flex flex-col items-center gap-1.5 rounded-xl border border-white/[0.06] bg-white/[0.03] p-3 text-center transition active:scale-[0.97]"
                            >
                              <ItemIcon className="h-5 w-5 text-slate-300" />
                              <span className="text-[10px] font-bold leading-tight text-slate-300">
                                {item.label}
                              </span>
                            </button>
                          )
                        })}
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </>
        )}

        {search.trim() && (
          <section className="mt-2 space-y-4">
            {/* Users */}
            {(() => {
              const q = search.trim()
              const showUsers = q.startsWith('@') || q.length >= 2
              if (!showUsers) return null

              const displayUsers = users
              if (loadingUsers) {
                return (
                  <div>
                    <h3 className="px-1 text-sm font-black uppercase tracking-[0.2em] text-zinc-300">Users</h3>
                    <div className="mt-2 space-y-2">
                      {Array.from({ length: 3 }).map((_, i) => (
                        <div key={i} className={`${neonCard} h-14 animate-pulse`} />
                      ))}
                    </div>
                  </div>
                )
              }

              if (displayUsers.length === 0) {
                return null
              }

              return (
                <div>
                  <h3 className="px-1 text-sm font-black uppercase tracking-[0.2em] text-zinc-300">Users</h3>
                  <div className="mt-2 space-y-2">
                    {displayUsers.map((user) => (
                      <button
                        key={user.id}
                        onClick={() => navigate(`/profile/${user.username}`)}
                        className={`${neonCard} flex w-full items-center gap-3 px-4 py-3 text-left transition active:scale-[0.985]`}
                      >
                        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-[#8b00ff] to-[#00BFFF] text-xs font-black text-white">
                          {(user.username || '?').charAt(0).toUpperCase()}
                        </div>
                        <div className="min-w-0">
                          <p className="truncate text-xs font-black text-white">@{user.username}</p>
                          {user.display_name && <p className="truncate text-[10px] text-zinc-400">{user.display_name}</p>}
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              )
            })()}

            {/* Hashtag / text posts */}
            {(() => {
              const q = search.trim()
              const isTag = q.startsWith('#')
              const term = isTag ? q.slice(1).toLowerCase() : q.toLowerCase()

              const matchedPosts = isTag
                ? posts.filter((post) => post.content.toLowerCase().includes(`#${term}`))
                : posts.filter((post) => post.content.toLowerCase().includes(term))

              if (matchedPosts.length === 0) return null

              return (
                <div>
                  <h3 className="px-1 text-sm font-black uppercase tracking-[0.2em] text-zinc-300">
                    {isTag ? 'Hashtag Posts' : 'Matching Posts'}
                  </h3>
                  <div className="mt-2 space-y-2">
                    {matchedPosts.slice(0, 8).map((post) => (
                      <button
                        key={post.id}
                        onClick={() => navigate('/community-wall')}
                        className={`${neonCard} w-full px-4 py-3 text-left transition active:scale-[0.985]`}
                      >
                        <div className="flex items-center gap-2">
                          <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-[#8b00ff] to-[#00BFFF] text-[10px] font-black text-white">
                            {(post.username || '?').charAt(0).toUpperCase()}
                          </div>
                          <span className="truncate text-xs font-black text-white">{post.username || 'Unknown'}</span>
                          <span className="text-[9px] font-bold text-zinc-500">{getTimeSince(post.created_at)}</span>
                        </div>
                        <p className="mt-1.5 line-clamp-2 text-xs leading-5 text-zinc-300">{post.content}</p>
                      </button>
                    ))}
                  </div>
                </div>
              )
            })()}

            {/* Pages */}
            {filteredPages.length > 0 ? (
              <div>
                <h3 className="px-1 text-sm font-black uppercase tracking-[0.2em] text-zinc-300">Pages</h3>
                <div className="mt-2 grid grid-cols-3 gap-2">
                  {filteredPages.map((item) => {
                    const ItemIcon = item.icon
                    return (
                      <button
                        key={item.path + item.label}
                        onClick={() => navigate(item.path)}
                        className="flex flex-col items-center gap-1.5 rounded-xl border border-white/[0.06] bg-white/[0.03] p-3 text-center transition active:scale-[0.97]"
                      >
                        <ItemIcon className="h-5 w-5 text-slate-300" />
                        <span className="text-[10px] font-bold leading-tight text-slate-300">{item.label}</span>
                      </button>
                    )
                  })}
                </div>
              </div>
            ) : (
              !loadingUsers &&
              users.length === 0 && (
                <p className="mt-4 text-center text-xs text-zinc-500">
                  No results for &quot;{search}&quot;
                </p>
              )
            )}
          </section>
        )}
      </main>
    </div>
  )
}

import React, {
  useCallback,
  useEffect,
  useRef,
  useState,
} from 'react'
import { useNavigate } from 'react-router-dom'
import {
  ArrowLeft,
  Camera,
  CameraOff,
  ChevronDown,
  Loader2,
  Mic,
  MicOff,
  Radio,
  RefreshCw,
  VideoOff,
  X,
} from 'lucide-react'
import { toast } from 'sonner'

import {
  LocalAudioTrack,
  LocalVideoTrack,
  Room,
  Track,
} from 'livekit-client'

import { supabase } from '@/lib/supabase'
import { useAuthStore } from '@/lib/store'
import { PreflightStore } from '@/lib/preflightStore'
import { usePreflightStore } from '@/lib/preflightStore'
import { requestLiveKitToken } from '@/lib/livekitToken'
import { awardKeyToUser } from '@/services/keyService'
import { useKeyDiscoveryStore } from '@/stores/useKeyDiscoveryStore'
import { useBroadcastViewerCap } from '@/hooks/useBroadcastViewerCap'
import CameraOffImageUpload from '@/components/broadcast/CameraOffImageUpload'
import { MAX_GUEST_SEATS } from '@/config/broadcastCategories'

type BroadcastCategory =
  | 'general'
  | 'gaming'
  | 'podcast'
  | 'irl'
  | 'education'
  | 'fitness'
  | 'business'
  | 'spiritual'
  | 'debate'

const CATEGORIES: Array<{
  id: BroadcastCategory
  name: string
  icon: string
}> = [
  { id: 'general', name: 'General', icon: '🎥' },
  { id: 'gaming', name: 'Gaming', icon: '🎮' },
  { id: 'podcast', name: 'Podcast', icon: '🎙️' },
  { id: 'irl', name: 'IRL', icon: '📱' },
  { id: 'education', name: 'Education', icon: '📚' },
  { id: 'fitness', name: 'Fitness', icon: '💪' },
  { id: 'business', name: 'Business', icon: '💼' },
  { id: 'spiritual', name: 'Spiritual', icon: '🙏' },
  { id: 'debate', name: 'Debate', icon: '⚖️' },
]

export default function PhoneGoLive() {
  const navigate = useNavigate()

  const { user, profile } = useAuthStore()

  const videoRef = useRef<HTMLVideoElement | null>(null)
  const streamRef = useRef<MediaStream | null>(null)
  const roomRef = useRef<Room | null>(null)

  const mountedRef = useRef(true)
  const startingRef = useRef(false)
  const keyAwardedRef = useRef(false)

  // Safety net: if broadcast start hangs, force-reset the guard so the
  // user can retry instead of being stuck on a frozen button.
  const START_BROADCAST_TIMEOUT_MS = 30_000;
  const startSafetyTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [title, setTitle] = useState('')
  const [category, setCategory] =
    useState<BroadcastCategory>('general')
  const [seatCount, setSeatCount] = useState(0)

  const [cameraOn, setCameraOn] = useState(true)
  const [micOn, setMicOn] = useState(true)

  const [facingMode, setFacingMode] =
    useState<'user' | 'environment'>('user')

  const [loading, setLoading] = useState(true)
  const [starting, setStarting] = useState(false)
  const [permissionError, setPermissionError] = useState<string | null>(null)

  const [cameraTrack, setCameraTrack] =
    useState<LocalVideoTrack | null>(null)

  const [microphoneTrack, setMicrophoneTrack] =
    useState<LocalAudioTrack | null>(null)

  const {
    startCapEnabled,
    startCapMax,
    viewerCapEnabled,
    viewerCapMax,
    viewerCapHours,
    seatCapEnabled,
    seatCapMax,
    allRestrictionsDisabled,
    loading: capLoading,
  } = useBroadcastViewerCap()

  const maxGuestSeats = seatCapEnabled
    ? Math.max(0, Math.min(MAX_GUEST_SEATS, seatCapMax))
    : MAX_GUEST_SEATS
  const configuredSeatCount = Math.max(0, Math.min(seatCount, maxGuestSeats))

  /*
   * Attach the native MediaStream to the phone preview.
   */
  const attachPreview = useCallback((mediaStream: MediaStream) => {
    const video = videoRef.current

    if (!video) return

    video.srcObject = mediaStream
    video.muted = true
    video.playsInline = true

    video.play().catch(() => {})
  }, [])

  /*
   * Stop all currently owned media.
   */
  const stopMedia = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        try {
          track.stop()
        } catch {}
      })

      streamRef.current = null
    }

    if (videoRef.current) {
      videoRef.current.srcObject = null
    }
  }, [])

  /*
   * Acquire camera + microphone.
   */
  const acquireMedia = useCallback(
    async (
      requestedFacingMode: 'user' | 'environment' = facingMode
    ) => {
      if (
        !navigator.mediaDevices ||
        !navigator.mediaDevices.getUserMedia
      ) {
        throw new Error(
          'Camera and microphone are not supported by this browser.'
        )
      }

      const mediaStream =
        await navigator.mediaDevices.getUserMedia({
          audio: {
            echoCancellation: true,
            noiseSuppression: true,
            autoGainControl: true,
          },
          video: {
            facingMode: requestedFacingMode,
            width: {
              ideal: 1280,
            },
            height: {
              ideal: 720,
            },
          },
        })

      if (!mountedRef.current) {
        mediaStream.getTracks().forEach(track => track.stop())
        return null
      }

      streamRef.current = mediaStream

      const audio = mediaStream.getAudioTracks()[0]
      const video = mediaStream.getVideoTracks()[0]

      setMicOn(!!audio)
      setCameraOn(!!video)

      attachPreview(mediaStream)

      return mediaStream
    },
    [attachPreview, facingMode]
  )

  /*
   * Initial camera/microphone permission request.
   */
  useEffect(() => {
    mountedRef.current = true

    const initialize = async () => {
      try {
        setLoading(true)
        setPermissionError(null)

        await acquireMedia('user')
      } catch (error: any) {
        console.error(
          '[PhoneGoLive] Media permission error:',
          error
        )

        setPermissionError(
          error?.message ||
            'Camera and microphone access is required.'
        )
      } finally {
        if (mountedRef.current) {
          setLoading(false)
        }
      }
    }

    initialize()

    return () => {
      mountedRef.current = false

      if (!startingRef.current) {
        stopMedia()
      }
    }
  }, [acquireMedia, stopMedia])

  /*
   * Toggle microphone.
   */
  const toggleMic = useCallback(() => {
    const stream = streamRef.current

    if (!stream) return

    const nextState = !micOn

    stream.getAudioTracks().forEach(track => {
      track.enabled = nextState
    })

    if (microphoneTrack) {
      microphoneTrack.mediaStreamTrack.enabled = nextState
    }

    setMicOn(nextState)
  }, [micOn, microphoneTrack])

  /*
   * Toggle camera.
   */
  const toggleCamera = useCallback(() => {
    const stream = streamRef.current

    if (!stream) return

    const nextState = !cameraOn

    stream.getVideoTracks().forEach(track => {
      track.enabled = nextState
    })

    if (cameraTrack) {
      cameraTrack.mediaStreamTrack.enabled = nextState
    }

    setCameraOn(nextState)
  }, [cameraOn, cameraTrack])

  /*
   * Flip front/rear camera.
   */
  const flipCamera = useCallback(async () => {
    if (startingRef.current) return

    const nextFacingMode =
      facingMode === 'user'
        ? 'environment'
        : 'user'

    try {
      const oldStream = streamRef.current

      if (oldStream) {
        oldStream.getVideoTracks().forEach(track => {
          try {
            track.stop()
          } catch {}
        })
      }

      const newStream =
        await navigator.mediaDevices.getUserMedia({
          audio: false,
          video: {
            facingMode: nextFacingMode,
            width: {
              ideal: 1280,
            },
            height: {
              ideal: 720,
            },
          },
        })

      const newVideo =
        newStream.getVideoTracks()[0]

      if (!newVideo) {
        throw new Error('No camera was found.')
      }

      /*
       * Keep the existing microphone.
       */
      const currentStream = streamRef.current
      const microphone =
        currentStream?.getAudioTracks()[0]

      const combinedStream = new MediaStream()

      if (microphone) {
        combinedStream.addTrack(microphone)
      }

      combinedStream.addTrack(newVideo)

      streamRef.current = combinedStream

      setFacingMode(nextFacingMode)
      setCameraOn(true)

      attachPreview(combinedStream)

      /*
       * If a LiveKit track already exists during setup,
       * replace its underlying media track.
       */
      if (cameraTrack) {
        try {
          await cameraTrack.replaceTrack(newVideo)
        } catch (error) {
          console.warn(
            '[PhoneGoLive] Failed to replace LiveKit camera track',
            error
          )
        }
      }
    } catch (error) {
      console.error(
        '[PhoneGoLive] Failed to flip camera:',
        error
      )

      toast.error('Unable to switch cameras.')
    }
  }, [
    attachPreview,
    cameraTrack,
    facingMode,
  ])

  /*
   * Build the LiveKit tracks from the native stream.
   */
  const createLiveKitTracks = useCallback(
    (mediaStream: MediaStream) => {
      const audio =
        mediaStream.getAudioTracks()[0]

      const video =
        mediaStream.getVideoTracks()[0]

      const audioTrack = audio
        ? new LocalAudioTrack(audio)
        : null

      const videoTrack = video
        ? new LocalVideoTrack(video)
        : null

      if (audioTrack) {
        audioTrack.source = Track.Source.Microphone
      }

      if (videoTrack) {
        videoTrack.source = Track.Source.Camera
      }

      return {
        audioTrack,
        videoTrack,
      }
    },
    []
  )

  /*
   * Start the actual broadcast.
   */
  const startBroadcast = useCallback(async () => {
    if (startingRef.current) return

    if (!user?.id) {
      toast.error('You must be signed in to go live.')
      return
    }

    if (!title.trim()) {
      toast.error('Enter a title for your broadcast.')
      return
    }

    if (!cameraOn) {
      toast.error('Camera must be enabled to start your broadcast.')
      return
    }

    if (!micOn) {
      toast.error('Microphone must be enabled to start your broadcast.')
      return
    }

    if (!import.meta.env.VITE_LIVEKIT_URL) {
      toast.error('LiveKit is not configured.')
      return
    }

    startingRef.current = true
    setStarting(true)

    // Safety net: if broadcast start hangs, force-reset the guard so the
    // user can retry instead of being stuck on a frozen button.
    if (startSafetyTimeoutRef.current) {
      clearTimeout(startSafetyTimeoutRef.current);
    }
    startSafetyTimeoutRef.current = setTimeout(() => {
      startingRef.current = false;
      startSafetyTimeoutRef.current = null;
    }, START_BROADCAST_TIMEOUT_MS);

    let streamId: string | null = null
    let room: Room | null = null

    try {
      /*
       * Make sure we have a current native stream.
       */
      let mediaStream = streamRef.current

      if (!mediaStream) {
        mediaStream = await acquireMedia(facingMode)

        if (!mediaStream) {
          throw new Error(
            'Camera and microphone are unavailable.'
          )
        }
      }

      const {
        audioTrack,
        videoTrack,
      } = createLiveKitTracks(mediaStream)

      if (!audioTrack || !videoTrack) {
        throw new Error(
          'Camera and microphone tracks could not be created.'
        )
      }

      setMicrophoneTrack(audioTrack)
      setCameraTrack(videoTrack)

      /*
       * Generate a unique stream/room ID.
       */
      streamId =
        crypto.randomUUID()

      const roomName = streamId

      /*
       * Create the Supabase stream row first.
       */
      const insertData = {
        id: streamId,
        user_id: user.id,
        broadcaster_id: user.id,
        streamer_id: user.id,
        owner_id: user.id,

        title: title.trim(),
        category,

        stream_type: 'standard',

        camera_ready: true,

        status: 'starting',
        is_live: false,

        started_at: null,

        box_count: configuredSeatCount + 1,
        seat_count: configuredSeatCount,

        layout_mode: 'grid',

        livekit_room_name: roomName,
        agora_channel: roomName,

        broadcast_disclaimer_accepted: true,
        broadcast_disclaimer_accepted_at:
          new Date().toISOString(),
        broadcast_disclaimer_user_id: user.id,
      }

      const {
        data,
        error,
      } = await supabase
        .from('streams')
        .insert(insertData)
        .select()
        .single()

      if (error) {
        throw error
      }

      streamId = data.id

      /*
       * Request LiveKit token using the same backend
       * endpoint/function used by the desktop setup.
       */
      const tokenData = await requestLiveKitToken(roomName, user.id)

      /*
       * Connect to LiveKit.
       */
      room = new Room({
        audioCaptureOptions: {
          echoCancellation: true,
          noiseSuppression: true,
        },
        videoCaptureOptions: {
          facingMode,
        },
        dynacast: true,
      } as any)

      await room.connect(
        import.meta.env.VITE_LIVEKIT_URL,
        tokenData.token
      )

      roomRef.current = room

      /*
       * Publish microphone and camera.
       */
      await room.localParticipant.publishTrack(
        audioTrack
      )

      await room.localParticipant.publishTrack(
        videoTrack
      )

      /*
       * Preserve the exact LiveKit objects so
       * BroadcastPage can reuse the existing connection.
       */
      PreflightStore.setLivekitRoom(room)

      PreflightStore.setLivekitTracks([
        audioTrack,
        videoTrack,
      ])

      PreflightStore.setTrackEnabledStates(
        true,
        true
      )

      usePreflightStore
        .getState()
        .setPreflightConnection({
          room,
          audioTrack,
          videoTrack,
          streamId,
          roomName,
        })

      PreflightStore.setTransferSession({
        room,
        roomName,
        streamId,
        participantIdentity:
          tokenData.participantIdentity ||
          user.id,

        cameraTrack: videoTrack,
        microphoneTrack: audioTrack,

        screenTrack: null,
        screenAudioTrack: null,

        mode: 'camera',

        cameraOverlayEnabled: false,

        transferredAt: Date.now(),

        ownership: 'broadcast-page',

        transitionInProgress: true,
      })

      /*
       * Mark the Supabase stream LIVE only after
       * LiveKit has connected and tracks published.
       */
      const {
        error: liveError,
      } = await supabase
        .from('streams')
        .update({
          status: 'live',
          is_live: true,
          started_at:
            new Date().toISOString(),
        })
        .eq('id', streamId)

      if (liveError) {
        throw liveError
      }

      if (!keyAwardedRef.current) {
        keyAwardedRef.current = true
        void (async () => {
          try {
            const result = await awardKeyToUser(user.id)
            if (result?.success && result.key_letter) {
              useKeyDiscoveryStore.getState().openDiscovery({
                key_letter: result.key_letter,
                rarity: result.rarity || 'COMMON',
                value: result.value || 0,
                is_key_to_city: !!result.is_key_to_city,
                cashout_available_at: result.cashout_available_at || new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
              })
            }
          } catch {
            // non-blocking
          }
        })()
      }

      /*
       * Let the next page know this is a live
       * stream transition.
       */
      sessionStorage.setItem(
        'tc_starting_stream',
        'true'
      )

      sessionStorage.setItem(
        'tc_camera_facing_mode',
        facingMode
      )

      sessionStorage.setItem(
        'tc_video_enabled',
        'true'
      )

      sessionStorage.setItem(
        'tc_audio_enabled',
        'true'
      )

      /*
       * IMPORTANT:
       * Do not stop the tracks here.
       *
       * BroadcastPage owns them now. Keep `startingRef` true so the
       * unmount cleanup leaves the LiveKit-owned camera/mic tracks running
       * (stopping them here would kill the broadcast camera on the phone).
       */
      startingRef.current = true

      navigate(`/broadcast/${streamId}`)
    } catch (error: any) {
      console.error(
        '[PhoneGoLive] Broadcast failed:',
        error
      )

      if (streamId) {
        try {
          await supabase
            .from('streams')
            .update({
              status: 'failed',
              is_live: false,
            })
            .eq('id', streamId)
        } catch {
          // ignore
        }
      }

      if (room) {
        try {
          room.disconnect()
        } catch {}
      }

      toast.error(
        error?.message ||
          'Unable to start your broadcast.'
      )

      startingRef.current = false
      // Clear safety timeout on success so it doesn't erroneously reset the guard later.
      if (startSafetyTimeoutRef.current) {
        clearTimeout(startSafetyTimeoutRef.current);
        startSafetyTimeoutRef.current = null;
      }
    } finally {
      if (mountedRef.current) {
        setStarting(false)
      }
    }
  }, [
    acquireMedia,
    cameraOn,
    category,
    configuredSeatCount,
    createLiveKitTracks,
    facingMode,
    micOn,
    navigate,
    title,
    user?.id,
  ])

  /*
   * Leave setup without starting.
   */
  const handleClose = useCallback(() => {
    if (startingRef.current) return

    stopMedia()

    navigate(-1)
  }, [navigate, stopMedia])

  /*
   * Browser back / component cleanup.
   */
  useEffect(() => {
    const handleBeforeUnload = () => {
      if (!startingRef.current) {
        stopMedia()
      }
    }

    window.addEventListener(
      'beforeunload',
      handleBeforeUnload
    )

    return () => {
      window.removeEventListener(
        'beforeunload',
        handleBeforeUnload
      )

      mountedRef.current = false

      if (!startingRef.current) {
        stopMedia()
      }
    }
  }, [stopMedia])

  return (
    <div className="min-h-screen bg-gradient-to-b from-[#090014] via-black to-[#090014] text-white">
      {/* Header */}
      <header className="sticky top-0 z-30 flex h-14 items-center justify-between border-b border-fuchsia-500/20 bg-black/90 px-4 backdrop-blur-xl">
        <button
          type="button"
          onClick={handleClose}
          disabled={starting}
          className="flex h-12 w-12 items-center justify-center rounded-full bg-white/10 text-white transition hover:bg-white/20 disabled:opacity-40"
        >
          <ArrowLeft size={26} className="text-white drop-shadow-[0_0_8px_rgba(255,255,255,0.6)]" />
        </button>

        <div className="flex items-center gap-2">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-cyan-400 to-fuchsia-500 shadow-[0_0_18px_rgba(168,85,247,.35)]">
            <Radio size={16} />
          </div>

          <div>
            <h1 className="text-sm font-black">
              Go Live
            </h1>

            <p className="text-[9px] uppercase tracking-widest text-zinc-500">
              Broadcast Setup
            </p>
          </div>
        </div>

        <button
          type="button"
          onClick={handleClose}
          disabled={starting}
          className="flex h-12 w-12 items-center justify-center rounded-full bg-white/10 text-white transition hover:bg-white/20 disabled:opacity-40"
        >
          <X size={26} className="text-white drop-shadow-[0_0_8px_rgba(255,255,255,0.6)]" />
        </button>
      </header>

      <main className="mx-auto w-full max-w-xl space-y-4 p-4 pb-8">
        {/* Camera */}
        <section className="relative mx-auto aspect-video max-h-[28vh] w-full max-w-sm overflow-hidden rounded-3xl border border-fuchsia-500/20 bg-zinc-950 shadow-[0_0_40px_rgba(168,85,247,.12)]">
          {permissionError ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-6 text-center">
              <CameraOff
                size={46}
                className="mb-4 text-red-400"
              />

              <h2 className="mb-2 text-base font-bold">
                Camera Access Required
              </h2>

              <p className="mb-5 max-w-xs text-xs leading-relaxed text-zinc-400">
                {permissionError}
              </p>

              <button
                type="button"
                onClick={async () => {
                  try {
                    setPermissionError(null)
                    await acquireMedia(
                      facingMode
                    )
                  } catch (error: any) {
                    setPermissionError(
                      error?.message ||
                        'Unable to access camera.'
                    )
                  }
                }}
                className="rounded-xl bg-gradient-to-r from-cyan-400 to-fuchsia-500 px-5 py-3 text-xs font-black text-black"
              >
                Allow Camera & Mic
              </button>
            </div>
          ) : (
            <video
              ref={videoRef}
              muted
              autoPlay
              playsInline
              className={`absolute inset-0 h-full w-full object-cover -scale-x-100 ${
                cameraOn
                  ? ''
                  : 'opacity-0'
              }`}
            />
          )}

          {!cameraOn && !permissionError && (
            <div className="absolute inset-0 flex items-center justify-center bg-zinc-950">
              <VideoOff
                size={48}
                className="text-zinc-700"
              />
            </div>
          )}

          {/* Preview badge */}
          <div className="absolute left-3 top-3 flex items-center gap-2 rounded-full border border-white/10 bg-black/70 px-3 py-1.5 text-[10px] font-bold backdrop-blur">
            <span className="h-2 w-2 rounded-full bg-emerald-400 shadow-[0_0_8px_rgba(52,211,153,.8)]" />
            PREVIEW
          </div>

          {/* Camera controls */}
          {!permissionError && (
            <div className="absolute bottom-4 left-0 right-0 flex justify-center gap-3">
              <button
                type="button"
                onClick={toggleMic}
                className={`flex h-12 w-12 items-center justify-center rounded-full border backdrop-blur-xl transition ${
                  micOn
                    ? 'border-white/10 bg-black/70'
                    : 'border-red-500/40 bg-red-600/80'
                }`}
              >
                {micOn ? (
                  <Mic size={20} />
                ) : (
                  <MicOff size={20} />
                )}
              </button>

              <button
                type="button"
                onClick={toggleCamera}
                className={`flex h-12 w-12 items-center justify-center rounded-full border backdrop-blur-xl transition ${
                  cameraOn
                    ? 'border-white/10 bg-black/70'
                    : 'border-red-500/40 bg-red-600/80'
                }`}
              >
                {cameraOn ? (
                  <Camera size={20} />
                ) : (
                  <CameraOff size={20} />
                )}
              </button>

              <button
                type="button"
                onClick={flipCamera}
                className="flex h-12 w-12 items-center justify-center rounded-full border border-white/10 bg-black/70 backdrop-blur-xl"
              >
                <RefreshCw size={20} />
              </button>
            </div>
          )}
        </section>

        {/* Camera Off Image */}
        <section className="space-y-2">
          <label className="px-1 text-[10px] font-bold uppercase tracking-widest text-zinc-500">
            Camera Off Image
          </label>
          <p className="px-1 text-[10px] text-zinc-600">
            Show this image when your camera is off during broadcast
          </p>
          <CameraOffImageUpload />
        </section>

        {/* Title */}
        <section className="space-y-2">
          <label className="px-1 text-[10px] font-bold uppercase tracking-widest text-zinc-500">
            Stream Title
          </label>

          <input
            value={title}
            onChange={e =>
              setTitle(e.target.value)
            }
            disabled={starting}
            maxLength={120}
            placeholder="What are you doing?"
            className="w-full rounded-2xl border border-white/10 bg-zinc-900/80 px-4 py-3.5 text-sm outline-none transition placeholder:text-zinc-600 focus:border-fuchsia-500/50"
          />
        </section>

        {/* Category */}
        <section className="space-y-2">
          <label className="px-1 text-[10px] font-bold uppercase tracking-widest text-zinc-500">
            Category
          </label>

          <div className="relative">
            <select
              value={category}
              onChange={e =>
                setCategory(
                  e.target.value as BroadcastCategory
                )
              }
              disabled={starting}
              className="w-full appearance-none rounded-2xl border border-white/10 bg-zinc-900/80 px-4 py-3.5 pr-10 text-sm font-semibold outline-none focus:border-fuchsia-500/50"
            >
              {CATEGORIES.map(item => (
                <option
                  key={item.id}
                  value={item.id}
                  className="bg-zinc-900"
                >
                  {item.icon} {item.name}
                </option>
              ))}
            </select>

            <ChevronDown
              size={18}
              className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-zinc-500"
            />
          </div>
        </section>

        {/* Guest seats */}
        <section className="space-y-2">
          <label className="px-1 text-[10px] font-bold uppercase tracking-widest text-zinc-500">
            Guest Seats
          </label>
          <div className="flex items-center justify-between rounded-2xl border border-cyan-500/15 bg-cyan-500/5 px-4 py-3">
            <div>
              <p className="text-sm font-bold text-white">Available seats</p>
              <p className="mt-0.5 text-[10px] text-zinc-500">Host is not included</p>
            </div>
            <div className="flex items-center gap-3">
              <button
                type="button"
                onClick={() => setSeatCount(Math.max(0, configuredSeatCount - 1))}
                disabled={starting || configuredSeatCount <= 0}
                className="grid h-9 w-9 place-items-center rounded-lg border border-white/10 bg-white/5 text-white disabled:cursor-not-allowed disabled:opacity-40"
                aria-label="Remove a guest seat"
              >
                -
              </button>
              <span className="min-w-12 text-center text-sm font-black text-cyan-200">
                {configuredSeatCount} / {maxGuestSeats}
              </span>
              <button
                type="button"
                onClick={() => setSeatCount(Math.min(maxGuestSeats, configuredSeatCount + 1))}
                disabled={starting || configuredSeatCount >= maxGuestSeats}
                className="grid h-9 w-9 place-items-center rounded-lg border border-cyan-300/25 bg-cyan-400/10 text-cyan-100 disabled:cursor-not-allowed disabled:opacity-40"
                aria-label="Add a guest seat"
              >
                +
              </button>
            </div>
          </div>
        </section>

        {/* Broadcast Limits */}
        {!capLoading && !allRestrictionsDisabled && (
          <section className="space-y-2">
            <p className="px-1 text-[10px] font-bold uppercase tracking-widest text-zinc-500">
              Broadcast Limits
            </p>

            <div className="grid grid-cols-2 gap-2">
              {startCapEnabled && (
                <div className="rounded-2xl border border-amber-500/10 bg-amber-500/5 px-3 py-2.5">
                  <p className="text-[9px] font-black uppercase tracking-wider text-amber-400/80">
                    Start Cap
                  </p>
                  <p className="mt-1 text-sm font-black text-amber-300">
                    {startCapMax} live
                  </p>
                  <p className="text-[9px] text-zinc-500">
                    Max concurrent broadcasts
                  </p>
                </div>
              )}

              {viewerCapEnabled && (
                <div className="rounded-2xl border border-fuchsia-500/10 bg-fuchsia-500/5 px-3 py-2.5">
                  <p className="text-[9px] font-black uppercase tracking-wider text-fuchsia-400/80">
                    Viewer Cap
                  </p>
                  <p className="mt-1 text-sm font-black text-fuchsia-300">
                    {viewerCapMax} viewers
                  </p>
                  <p className="text-[9px] text-zinc-500">
                    Per stream for {viewerCapHours}h
                  </p>
                </div>
              )}

              {seatCapEnabled && (
                <div className="rounded-2xl border border-cyan-500/10 bg-cyan-500/5 px-3 py-2.5">
                  <p className="text-[9px] font-black uppercase tracking-wider text-cyan-400/80">
                    Seat Cap
                  </p>
                  <p className="mt-1 text-sm font-black text-cyan-300">
                    {seatCapMax} boxes
                  </p>
                  <p className="text-[9px] text-zinc-500">
                    Max seats per broadcast
                  </p>
                </div>
              )}

              {allRestrictionsDisabled && (
                <div className="rounded-2xl border border-emerald-500/10 bg-emerald-500/5 px-3 py-2.5">
                  <p className="text-[9px] font-black uppercase tracking-wider text-emerald-400/80">
                    Restrictions
                  </p>
                  <p className="mt-1 text-sm font-black text-emerald-300">
                    Off
                  </p>
                  <p className="text-[9px] text-zinc-500">
                    All limits removed
                  </p>
                </div>
              )}
            </div>
          </section>
        )}

        {/* Status */}
        <div className="flex items-center justify-between rounded-2xl border border-cyan-500/10 bg-cyan-500/5 px-4 py-3">
          <div>
            <p className="text-xs font-bold">
              Camera & Microphone
            </p>

            <p className="mt-0.5 text-[10px] text-zinc-500">
              Ready for LiveKit
            </p>
          </div>

          <div className="flex items-center gap-2 text-[10px] font-bold">
            <span
              className={
                micOn
                  ? 'text-emerald-400'
                  : 'text-red-400'
              }
            >
              MIC
            </span>

            <span
              className={
                cameraOn
                  ? 'text-emerald-400'
                  : 'text-red-400'
              }
            >
              CAM
            </span>
          </div>
        </div>

        {/* Go Live */}
        <button
          type="button"
          onClick={startBroadcast}
          disabled={
            starting ||
            loading ||
            !title.trim() ||
            !!permissionError ||
            !cameraOn ||
            !micOn
          }
          className="flex w-full items-center justify-center gap-2 rounded-2xl bg-gradient-to-r from-cyan-400 via-fuchsia-500 to-purple-600 py-4 text-sm font-black text-white shadow-[0_0_30px_rgba(168,85,247,.25)] transition active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-40"
        >
          {starting ? (
            <>
              <Loader2
                size={20}
                className="animate-spin"
              />
              Starting Broadcast...
            </>
          ) : (
            <>
              <Radio size={20} />
              GO LIVE
            </>
          )}
        </button>
      </main>
    </div>
  )
}

