      setAchRoutingNumber('')
      setAchAccountNumber('')

      await loadAllData()
      await loadCashoutLimit()
      await loadCashoutRequests()
      await loadTransactions()

      setActiveTab('requests')
    } catch (error: any) {
      toast.error(
        error?.message ||
          'Failed to submit cashout',
