      <span className="max-w-[72px] truncate text-[8px] font-black text-zinc-400">
        {story.isOwn ? 'Your Story' : story.username}
      </span>

      {/* Countdown to the 24h hard delete */}
      <ExpiryCountdown expiresAt={story.expiresAt} compact />
    </button>
  )
}

