  const handleSaveProfile = async () => {
    if (!user) return

    const cleanUsername =
      settingsUsername.trim().toLowerCase()

    const cleanFullName = fullName.trim()
    const cleanBio = bio.trim()

    if (!/^[a-zA-Z0-9_]{2,20}$/.test(cleanUsername)) {
      toast.error(
        'Username must be 2–20 characters using letters, numbers, or underscores.',
      )
      return
    }

    if (cleanBio.length > 500) {
      toast.error(
        'Bio must be 500 characters or fewer.',
      )
      return
    }

    setSavingProfile(true)

    try {
      if (
        username.toLowerCase() !== cleanUsername
      ) {
        const { data: existing, error } =
          await supabase
            .from('user_profiles')
            .select('id')
            .eq('username', cleanUsername)
            .neq('id', user.id)
            .maybeSingle()

        if (error) throw error

        if (existing) {
          toast.error(
            'That username is already taken.',
          )
          return
        }
      }

      const { error } = await supabase
        .from('user_profiles')
        .update({
          username: cleanUsername,
          full_name: cleanFullName || null,
          bio: cleanBio,
          platform: platform || null,
          banner_notifications_enabled:
            bannerNotifications,
          is_minor: isMinor,
          updated_at: new Date().toISOString(),
        })
        .eq('id', user.id)

      if (error) throw error

      await refreshProfile(true)

      setUsername(cleanUsername)
      setSettingsUsername(cleanUsername)

      setDisplayName(
        cleanFullName ||
          cleanUsername ||
          'User',
      )

      toast.success('Profile settings saved.')
    } catch (error) {
      console.error(
        '[PhoneProfile] Failed to save profile:',
        error,
      )

      toast.error(
        'Failed to save profile settings.',
      )
    } finally {
      setSavingProfile(false)
    }
  }

