============================================================================ */

function getDisplayName(
  profile: any,
  fallback = 'Broadcaster',
) {
  return (
    profile?.username ||
    profile?.email?.split?.('@')?.[0] ||
    fallback
  )
}

function getParticipantIdentity(
  participant: any,
): string {
  return String(
    participant?.identity ||
      participant?.participantIdentity ||
      participant?.name ||
      participant?.metadata?.user_id ||
      participant?.metadata?.userId ||
      '',
  )
}

function getParticipantMetadata(
  participant: any,
): any {
  const raw = participant?.metadata

  if (!raw) return {}

  if (typeof raw === 'object') {
    return raw
  }

  try {
    return JSON.parse(raw)
  } catch {
    return {}
  }
}

function normalizeUuid(value: unknown): string | null {
  const text = String(value || '').trim().toLowerCase()
  const match = text.match(
    /[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i,
  )
  return match?.[0]?.toLowerCase() || null
}

function resolveSeatParticipant(
  seat: any,
  participants: any[],
  room: any,
) {
  const seatUserId =
    seat?.user_id ||
    seat?.guest_id ||
    null

  const storedIdentity =
    String(
      seat?.livekit_participant_identity ||
        seat?.participant_identity ||
        seat?.livekit_identity ||
        seat?.seat_identity ||
        '',
    ).trim()

  const check = (participant: any) => {
    const participantIdentity =
      String(
        participant?.identity ||
          participant?.participantIdentity ||
          participant?.name ||
          '',
      ).trim()

    const metadata =
      getParticipantMetadata(participant)

    const participantUuid =
      normalizeUuid(participantIdentity)
    const metadataUuid =
      normalizeUuid(
        metadata.user_id ||
          metadata.userId ||
          metadata.uid,
      )
    const seatUuid =
      normalizeUuid(seatUserId)

    if (
      storedIdentity &&
      participantIdentity === storedIdentity
    ) {
      return true
    }

    if (
      storedIdentity &&
      participantUuid &&
      participantUuid === normalizeUuid(storedIdentity)
    ) {
      return true
    }

    if (
      seatUuid &&
      participantUuid &&
      participantUuid === seatUuid
    ) {
      return true
    }

    if (
      seatUuid &&
      metadataUuid &&
      metadataUuid === seatUuid
    ) {
      return true
    }

    if (
      !storedIdentity &&
      seatUserId &&
      (
        participantIdentity ===
          String(seatUserId) ||
        participantIdentity.endsWith(
          `-${seatUserId}`,
        ) ||
        participantIdentity.startsWith(
          `${seatUserId}-`,
        )
      )
    ) {
      return true
    }

    return false
  }

  let match =
    participants.find(check)

  if (
    !match &&
    room?.remoteParticipants
  ) {
    match =
      Array.from(
        room.remoteParticipants.values(),
      ).find(check)
  }

  return match || null
}

function participantMatchesUser(
  participant: any,
  userId?: string | null,
) {
  if (!participant || !userId) {
    return false
  }

  const identity =
    getParticipantIdentity(participant)

  const metadata =
    getParticipantMetadata(participant)

  return (
    identity === userId ||
    identity.includes(userId) ||
    identity.endsWith(`-${userId}`) ||
    identity.startsWith(`${userId}-`) ||
    metadata.user_id === userId ||
    metadata.userId === userId
  )
}

function getVideoTrackFromParticipant(
  participant: any,
): RemoteVideoTrack | null {
  if (!participant) {
    return null
  }

  const directCandidates = [
    participant.videoTrack,
    participant.cameraTrack,
    participant.track,
    participant.video,
  ]

  for (const candidate of directCandidates) {
    if (
      candidate?.attach &&
      candidate?.kind === Track.Kind.Video
    ) {
      return candidate as RemoteVideoTrack
    }

    if (
      candidate?.attach &&
      candidate?.mediaStreamTrack?.kind === 'video'
    ) {
      return candidate as RemoteVideoTrack
    }
  }

  const publications: RemoteTrackPublication[] = []

  const collect = (value: any) => {
    if (!value) return

    if (typeof value.values === 'function') {
      publications.push(
        ...Array.from(
          value.values(),
        ) as RemoteTrackPublication[],
      )
      return
    }

    if (Array.isArray(value)) {
      publications.push(...value)
    }
  }

  collect(participant.videoTrackPublications)
  collect(participant.trackPublications)
  collect(participant.tracks)
  collect(participant.publications)

  const cameraPub =
    publications.find(
      (pub: any) =>
        pub?.source === Track.Source.Camera &&
        pub?.track?.attach,
    ) ||
    publications.find(
      (pub: any) =>
        pub?.source !== Track.Source.Microphone &&
        pub?.kind === Track.Kind.Video &&
        pub?.track?.attach,
    ) ||
    publications.find(
      (pub: any) =>
        pub?.kind === Track.Kind.Video &&
        pub?.track?.attach,
    ) ||
    publications.find(
      (pub: any) =>
        pub?.track?.kind === Track.Kind.Video &&
        pub?.track?.attach,
    ) ||
    publications.find(
      (pub: any) =>
        pub?.track?.mediaStreamTrack?.kind === 'video' &&
        pub?.track?.attach,
    )

  return (
    cameraPub?.track as RemoteVideoTrack
  ) || null
}

function getAudioTrackFromParticipant(
  participant: any,
) {
  if (!participant) {
    return null
  }

  const publications: any[] = []

  const collect = (value: any) => {
    if (!value) return

    if (typeof value.values === 'function') {
      publications.push(
        ...Array.from(value.values()),
      )
      return
    }

    if (Array.isArray(value)) {
      publications.push(...value)
    }
  }

  collect(participant.audioTrackPublications)
  collect(participant.trackPublications)
  collect(participant.tracks)
  collect(participant.publications)

  const audioPub =
    publications.find(
      (pub: any) =>
        pub?.source === Track.Source.Microphone &&
        pub?.track?.attach,
    ) ||
    publications.find(
      (pub: any) =>
        pub?.kind === Track.Kind.Audio &&
        pub?.track?.attach,
    ) ||
    publications.find(
      (pub: any) =>
        pub?.track?.kind === Track.Kind.Audio &&
        pub?.track?.attach,
    ) ||
    publications.find(
      (pub: any) =>
        pub?.track?.mediaStreamTrack?.kind === 'audio' &&
        pub?.track?.attach,
    )

  return audioPub?.track || null
}

function getSeatPrice(
  stream: Stream | null,
  index: number,
) {
  if (!stream) {
    return 0
  }

  if (
    Array.isArray(
      (stream as any).seat_prices,
    ) &&
    typeof (stream as any).seat_prices[index] === 'number'
  ) {
    return Number(
      (stream as any).seat_prices[index],
    )
  }

  return Number(
    (stream as any).seat_price ?? 0,
  )
}

/* ============================================================================
   REMOTE VIDEO
============================================================================ */

const PhoneRemoteVideo = memo(
  function PhoneRemoteVideo({
    participant,
    room,
    className,
    fallback,
    mirror = false,
  }: {
    participant: any
    room?: any
    className?: string
    fallback: React.ReactNode
    mirror?: boolean
  }) {
    const videoRef =
      useRef<HTMLVideoElement | null>(null)

    const audioRef =
      useRef<HTMLAudioElement | null>(null)

    const attachedVideoRef =
      useRef<RemoteVideoTrack | null>(null)

    const attachedAudioIdRef =
      useRef<string | null>(null)

    const [trackTick, setTrackTick] =
      useState(0)

    const participantIdentityRef =
      useRef<string>('')

    participantIdentityRef.current =
      String(
        participant?.identity ||
          participant?.participantIdentity ||
          participant?.name ||
          '',
      ).trim()

    useEffect(() => {
      if (!room) return

      const identity =
        participantIdentityRef.current

      if (!identity) return

      const bump = () => {
        setTrackTick(
          value => value + 1,
        )
      }

      const handleTrackSubscribed = (
        _track: any,
        _publication: any,
        participant: any,
      ) => {
        const pIdentity =
          String(
            participant?.identity ||
              participant?.participantIdentity ||
              participant?.name ||
              '',
          ).trim()

        if (pIdentity === identity) {
          bump()
        }
      }

      const handleTrackUnsubscribed = (
        _track: any,
        _publication: any,
        participant: any,
      ) => {
        const pIdentity =
          String(
            participant?.identity ||
              participant?.participantIdentity ||
              participant?.name ||
              '',
          ).trim()

        if (pIdentity === identity) {
          bump()
        }
      }

      const handleParticipantConnected = (
        participant: any,
      ) => {
        const pIdentity =
          String(
            participant?.identity ||
              participant?.participantIdentity ||
              participant?.name ||
              '',
          ).trim()

        if (pIdentity === identity) {
          bump()
        }
      }

      const handleParticipantDisconnected = (
        participant: any,
      ) => {
        const pIdentity =
          String(
            participant?.identity ||
              participant?.participantIdentity ||
              participant?.name ||
              '',
          ).trim()

        if (pIdentity === identity) {
          bump()
        }
      }

      room.on(
        RoomEvent.TrackSubscribed,
        handleTrackSubscribed,
      )

      room.on(
        RoomEvent.TrackUnsubscribed,
        handleTrackUnsubscribed,
      )

      room.on(
        RoomEvent.ParticipantConnected,
        handleParticipantConnected,
      )

      room.on(
        RoomEvent.ParticipantDisconnected,
        handleParticipantDisconnected,
      )

      return () => {
        room.off(
          RoomEvent.TrackSubscribed,
          handleTrackSubscribed,
        )

        room.off(
          RoomEvent.TrackUnsubscribed,
          handleTrackUnsubscribed,
        )

        room.off(
          RoomEvent.ParticipantConnected,
          handleParticipantConnected,
        )

        room.off(
          RoomEvent.ParticipantDisconnected,
          handleParticipantDisconnected,
        )
      }
    }, [room])

    const videoTrack =
      getVideoTrackFromParticipant(
        participant,
      )

    const audioTrack =
      getAudioTrackFromParticipant(
        participant,
      )

    const videoTrackId =
      videoTrack?.mediaStreamTrack?.id ||
      videoTrack?.sid ||
      null

    const audioTrackId =
      audioTrack?.mediaStreamTrack?.id ||
      audioTrack?.sid ||
      null

    useEffect(() => {
      const video =
        videoRef.current

      if (!video) return

      const previous =
        attachedVideoRef.current

      const previousId =
        previous?.mediaStreamTrack?.id ||
        previous?.sid ||
        null

      if (previous && previousId) {
        if (
          videoTrackId &&
          previousId ===
            videoTrackId
        ) {
          return
        }

        if (!videoTrackId) {
          return
        }

        try {
          previous.detach(video)
        } catch {
          // ignore
        }

        attachedVideoRef.current = null
      }

      if (!videoTrack) {
        video.srcObject = null
        return
      }

      let cancelled = false

      const attach = async () => {
        try {
          video.autoplay = true
          video.playsInline = true
          video.muted = true

          video.setAttribute(
            'playsinline',
            '',
          )

          video.setAttribute(
            'webkit-playsinline',
            '',
          )

          videoTrack.attach(video)

          attachedVideoRef.current =
            videoTrack

          if (!cancelled) {
            await video.play()
          }
        } catch (error) {
          console.warn(
            '[PhoneViewerPage] remote video attach failed',
            error,
          )
        }
      }

      void attach()

      return () => {
        cancelled = true

        try {
          videoTrack.detach(video)
        } catch {
          // ignore
        }

        if (
          attachedVideoRef.current ===
          videoTrack
        ) {
          attachedVideoRef.current =
            null
        }
      }
    }, [
      videoTrackId,
      trackTick,
    ])

    useEffect(() => {
      const audio =
        audioRef.current

      if (!audio) return

      if (
        audioTrackId ===
        attachedAudioIdRef.current
      ) {
        return
      }

      if (audioTrack) {
        try {
          audioTrack.attach(audio)

          audio.autoplay = true

          audio.play().catch(
            () => {},
          )
        } catch {
          // ignore
        }
      }

      attachedAudioIdRef.current =
        audioTrackId
    }, [
      audioTrack,
      audioTrackId,
      trackTick,
    ])

    return (
      <div
        className={cn(
          'relative h-full w-full overflow-hidden bg-black',
          className,
        )}
      >
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          controls={false}
          disablePictureInPicture
          className={cn('absolute inset-0 h-full w-full object-cover', mirror && '-scale-x-100')}
        />

        <audio
          ref={audioRef}
          autoPlay
        />

        {!videoTrack &&
          !attachedVideoRef.current && (
            <div className="absolute inset-0">
              {fallback}
            </div>
          )}
      </div>
    )
  },
)

/* ============================================================================
   LOCAL VIDEO
============================================================================ */

function PhoneLocalVideo({
  videoTrack,
  className,
}: {
  videoTrack: LocalVideoTrack | null
  audioTrack?: LocalAudioTrack | null
  className?: string
}) {
  const videoRef =
    useRef<HTMLVideoElement | null>(null)

  useEffect(() => {
    const video =
      videoRef.current

    if (!video || !videoTrack) {
      return
    }

    try {
      videoTrack.attach(video)

      video.play().catch(
        () => {},
      )
    } catch {
      // ignore
    }

    return () => {
      try {
        videoTrack.detach(video)
      } catch {
        // ignore
      }
    }
  }, [videoTrack])

  return (
    <div
      className={cn(
        'relative h-full w-full overflow-hidden bg-black',
        className,
      )}
    >
        {videoTrack ? (
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          className="h-full w-full object-cover -scale-x-100"
        />
      ) : (
        <div className="flex h-full w-full items-center justify-center">
          <VideoOff className="h-6 w-6 text-white/40" />
        </div>
      )}
    </div>
  )
}

