============================================================================ */

export default function PhoneViewerPage() {
  const params =
    useParams()

  const navigate =
    useNavigate()

  const streamId =
    params.streamId ||
    params.id ||
    ''

  const [stream, setStream] =
    useState<Stream | null>(null)

  const resolvedStreamId =
    stream?.id || streamId

  const {
    user,
    profile,
  } = useAuthStore()

  const {
    featuredBroadcasters,
    featuredEvent,
    isFeaturedEvent,
    currentStreamFeatured,
    leaderboardOpen,
    openFeaturedLeaderboard,
    closeFeaturedLeaderboard,
  } = useFeaturedLive({
    streamId: resolvedStreamId || null,
    enabled: !!resolvedStreamId,
  })

  const hostId =
    stream?.user_id || ''

  useEffect(() => {
    const isActive = stream?.status === 'live' && stream?.is_live !== false
    if (!stream?.id || !isActive) return

    const contentType = (stream as any)?.category === 'gaming' || (stream as any)?.stream_type === 'hytro'
      ? 'hytrogame'
      : 'broadcast'
    const surface = contentType === 'hytrogame' ? 'hytrogames' : 'live_now'
    const metadata = {
      category: (stream as any)?.category,
      stream_type: (stream as any)?.stream_type,
      platform: 'phone',
    }

    recordSignalEventInBackground({
      eventType: 'impression',
      contentType,
      contentId: stream.id,
      creatorId: hostId || null,
      surface,
      metadata,
    })
    recordSignalEventInBackground({
      eventType: 'watch_start',
      contentType,
      contentId: stream.id,
      creatorId: hostId || null,
      surface,
      metadata,
    })

    const startedAt = Date.now()
    return () => {
      const secondsViewed = Math.round((Date.now() - startedAt) / 1000)
      if (secondsViewed >= 3 && secondsViewed < 30) {
        recordSignalEventInBackground({
          eventType: 'skip',
          contentType,
          contentId: stream.id,
          creatorId: hostId || null,
          surface,
          value: secondsViewed,
          metadata: { ...metadata, seconds_viewed: secondsViewed },
        })
      }
    }
  }, [hostId, stream?.category, stream?.id, stream?.is_live, stream?.status, stream?.stream_type])


  const [
    broadcasterProfile,
    setBroadcasterProfile,
  ] = useState<any>(null)

  const [loading, setLoading] =
    useState(true)

  const [error, setError] =
    useState<string | null>(null)

  const [viewerError, setViewerError] =
    useState<string | null>(null)

  const [showControls, setShowControls] =
    useState(true)

  const [floatingMessages, setFloatingMessages] =
    useState<Array<{id: string, username: string, content: string, timestamp: number, isSystem?: boolean}>>([])

  const [blockedUsernames, setBlockedUsernames] =
    useState<Set<string>>(new Set())

  const [chatInput, setChatInput] =
    useState('')

  const [viewerCount, setViewerCount] =
    useState(0)

  const [liked, setLiked] =
    useState(false)

  const [
    tapIndicators,
    setTapIndicators,
  ] = useState<Array<{
    id: string
    x: number
    y: number
  }>>([])

  const [seatFocus, setSeatFocus] =
    useState<number | null>(null)

  const [
    giftRecipientId,
    setGiftRecipientId,
  ] = useState<string | null>(null)

  const [
    isGiftModalOpen,
    setIsGiftModalOpen,
  ] = useState(false)

  const [
    isShareModalOpen,
    setIsShareModalOpen,
  ] = useState(false)

  const [
    isCashoutModalOpen,
    setIsCashoutModalOpen,
  ] = useState(false)

  const [
    userActionTarget,
    setUserActionTarget,
  ] = useState<{
    userId: string
    username?: string
    role?: string
    createdAt?: string
  } | null>(null)

  const [
    showViewerAction,
    setShowViewerAction,
  ] = useState(false)

  const [
    showModActionMenu,
    setShowModActionMenu,
  ] = useState(false)

  const [
    selectedSeatUserId,
    setSelectedSeatUserId,
  ] = useState<string | null>(null)

  const [
    broadcastRaidTarget,
    setBroadcastRaidTarget,
  ] = useState<string | null>(null)

  const [recentGifts, setRecentGifts] =
    useState<BroadcastGift[]>([])

  const processedGiftIdsRef =
    useRef<Set<string>>(new Set())

  const recentChatKeysRef =
    useRef<Map<string, number>>(new Map())

  const processedMessageIdsRef =
    useRef<Set<string>>(new Set())

  const floatingChatChannelRef =
    useRef<ReturnType<typeof supabase.channel> | null>(null)

  const { enqueueGift } = useTargetedGiftQueue()

  const streamEndedRef =
    useRef(false)

  const hasJoinedAudienceRef =
    useRef(false)

  const joiningAudienceRef =
    useRef(false)

  const currentRoomKeyRef =
    useRef<string | null>(null)

  const viewerIdentityRef =
    useRef<string>('')

  const joiningPublisherRef =
    useRef(false)

  const audienceJoinAttemptedKeyRef =
    useRef<string | null>(null)

  const audienceFailedUntilRef =
    useRef<number>(0)

  /*
   * ========================================================================
   * BATTLE STATE
   *
   * The viewer remains in the normal broadcast room.
   *
   * A battle is considered active when the stream receives a battle_id.
   * When battle_id becomes empty/null, the BattleArena disappears and the
   * normal broadcast automatically becomes visible again.
   * ========================================================================
   */

  const battleId = useMemo(() => {
    const value =
      (stream as any)?.battle_id ??
      (stream as any)?.battleId ??
      ''

    return String(value || '')
  }, [stream])

  const [
    battleActive,
    setBattleActive,
  ] = useState(Boolean(battleId))

  const previousBattleIdRef =
    useRef<string>('')

  useEffect(() => {
    const nextBattleId =
      String(battleId || '')

    const previousBattleId =
      previousBattleIdRef.current

    setBattleActive(
      Boolean(nextBattleId),
    )

    /*
     * Battle transition.
     */
    if (
      nextBattleId &&
      nextBattleId !== previousBattleId
    ) {
      previousBattleIdRef.current =
        nextBattleId

      setShowControls(false)

      /*
       * Keep chat and broadcast alive underneath
       * the battle. BattleArena owns the battle
       * experience.
       */
      return
    }

    /*
     * Battle ended.
     */
    if (
      !nextBattleId &&
      previousBattleId
    ) {
      previousBattleIdRef.current =
        ''

      setBattleActive(false)
      setShowControls(true)

      toast.success(
        'Battle ended',
      )
    }
  }, [battleId])

  /*
   * Stable anonymous viewer identity.
   */
  const anonViewerId =
    useMemo(() => {
    if (!resolvedStreamId) return ''

    if (
      typeof window ===
      'undefined'
    ) {
      return ''
    }

    const key =
      `guest-viewer:${resolvedStreamId}`

    try {
      const existing =
        window.sessionStorage.getItem(
          key,
        )

      if (existing) {
        return existing
      }

      const cryptoObj =
        (window as any).crypto

      let id = ''

      if (
        cryptoObj &&
        typeof cryptoObj.randomUUID ===
          'function'
      ) {
        id =
          `guest-viewer:${resolvedStreamId}:${cryptoObj.randomUUID()}`
      } else {
        id =
          `guest-viewer:${resolvedStreamId}:${Math.random()
            .toString(36)
            .slice(2, 12)}`
      }

      window.sessionStorage.setItem(
        key,
        id,
      )

      return id
    } catch {
      return (
        `guest-viewer:${resolvedStreamId}:${Math.random()
          .toString(36)
          .slice(2, 12)}`
