  ======================================================================== */

  useEffect(() => {
    let cancelled = false

    if (!streamId) {
      setError(
        'Missing stream ID',
      )

      setLoading(false)

      return
    }

    const loadStream =
      async () => {
        setLoading(true)
        setError(null)

        try {
          const streamQuery = supabase
            .from('streams')
            .select('*')

          const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(streamId)
          let data: any = null
          let streamError: any = null

          if (isUuid) {
            const result = await streamQuery.eq('id', streamId).maybeSingle()
            data = result.data
            streamError = result.error
          } else {
            const { data: owner, error: ownerError } = await supabase
              .from('user_profiles')
              .select('id')
              .eq('username', streamId)
              .maybeSingle()

            if (ownerError) {
              streamError = ownerError
            } else if (owner?.id) {
              const result = await streamQuery
                .eq('user_id', owner.id)
                .eq('is_live', true)
                .eq('status', 'live')
                .order('created_at', { ascending: false })
                .limit(1)
                .maybeSingle()
              data = result.data
              streamError = result.error
            }
          }

            if (cancelled) return

            if (streamError) {
              console.error(
                '[PhoneViewerPage] stream lookup failed',
                streamError,
              )

              setError(
                streamError.message ||
                  'Unable to load stream',
              )

              setStream(null)

              return
            }

            if (!data) {
              setError(
                'Stream not found',
              )

              setStream(null)

              return
            }

            setStream(
              data as Stream,
            )
        } catch (err) {
          if (cancelled) return

          console.error(
            '[PhoneViewerPage] stream lookup failed',
            err,
          )

          setError(
            'Unable to load stream',
          )

          setStream(null)
        } finally {
          if (!cancelled) {
            setLoading(false)
          }
        }
      }

    void loadStream()

    return () => {
      cancelled = true
    }
  }, [streamId])

  /* ========================================================================
     REALTIME STREAM UPDATES
  ======================================================================== */

   useEffect(() => {
     if (!resolvedStreamId) {
       return
     }

     const streamEndedRef = {
       current: false,
     }

     const channel =
       supabase
        .channel(
          `phone-viewer-stream:${resolvedStreamId}`,
        )
        .on(
          'postgres_changes',
          {
            event: 'UPDATE',
            schema: 'public',
            table: 'streams',
            filter: `id=eq.${resolvedStreamId}`,
          },
          payload => {
            const next =
              payload.new || {}

            /*
             * IMPORTANT:
             * Merge the realtime row into local stream state.
             *
             * This is what makes battle_id immediately available
             * when the broadcaster starts a battle.
             */
            setStream(
              previous => ({
                ...(previous || {}),
                ...next,
              } as Stream),
            )

            const status =
              String(
                next.status || '',
              ).toLowerCase()

            const endedAt =
              next.ended_at ||
              next.endedAt

            if (
              status === 'ended' ||
              endedAt
            ) {
              if (
                streamEndedRef.current
              ) {
                return
              }

              streamEndedRef.current =
                true

                void (async () => {
                  try {
                    await leaveAudience()
                  } catch {
                    // ignore
                  }

                   navigate(
                     `/broadcast/summary/${resolvedStreamId}`,
                     { replace: true },
                   )
                })()
            }
          },
        )
        .subscribe()

    return () => {
      void supabase.removeChannel(
        channel,
      )
    }
   }, [
     resolvedStreamId,
     navigate,
   ])

