      return
    }

    if (hasJoinedAudienceRef.current || joiningAudienceRef.current) {
      return
    }

    const isActiveStatus =
      String(
        stream?.status || '',
      ).toLowerCase() === 'live'

    if (!isActiveStatus) {
      return
    }

    joiningAudienceRef.current = true

    let mounted = true

    void joinAsAudience({
      userId: viewerIdentity,
      streamId: resolvedStreamId,
      roomName: roomId,
      viewerIdentity,
      publishCapable: false,
    })
      .then((res: any) => {
          if (!mounted) return

          if (typeof res !== 'string') {
            hasJoinedAudienceRef.current = true
            setViewerError(null)
            currentRoomKeyRef.current = `${resolvedStreamId}:${roomId}`
          } else {
            setViewerError(res)
          }
