        .catch((err: any) => {
          if (!mounted) return

          const message =
            err?.message ||
            err?.statusText ||
            String(err) ||
            'Failed to join broadcast'

          setViewerError(message)
        })
      .finally(() => {
        joiningAudienceRef.current = false
      })

