  ] =
    useState<BroadcasterState>({
      participant: null,
      videoTrack: null,
      audioTrack: null,
    })

  const updateBroadcasterState =
    useCallback(
      (participant: any) => {
        if (!participant) {
          return
        }

        const videoTrack =
          getVideoTrackFromParticipant(
            participant,
          )

        const audioTrack =
          getAudioTrackFromParticipant(
            participant,
          )

        setBroadcasterState(
          previous => {
            const previousIdentity =
              previous.participant
                ?.identity ||
              null

            const nextIdentity =
              participant?.identity ||
              null

            const previousVideoId =
              previous.videoTrack
                ?.mediaStreamTrack
                ?.id ||
              previous.videoTrack
                ?.sid ||
              null

            const nextVideoId =
              videoTrack
                ?.mediaStreamTrack
                ?.id ||
              videoTrack?.sid ||
              null

            const previousAudioId =
              previous.audioTrack
                ?.mediaStreamTrack
                ?.id ||
              previous.audioTrack
                ?.sid ||
              null

            const nextAudioId =
              audioTrack
                ?.mediaStreamTrack
                ?.id ||
              audioTrack?.sid ||
              null

            if (
              previousIdentity ===
                nextIdentity &&
              previousVideoId ===
                nextVideoId &&
              previousAudioId ===
                nextAudioId
            ) {
              return previous
            }

            return {
              participant,
              videoTrack,
              audioTrack,
            }
          },
        )
      },
      [],
    )

  function resolveBroadcasterParticipant(
    participants: any[],
    room: any,
    streamId: string,
    broadcasterUserId: string,
  ) {
    const expectedHostIdentity = `host_${streamId}`

    const matches = (participant: any) => {
      const identity =
        String(
          participant?.identity ||
            participant?.participantIdentity ||
            participant?.name ||
            '',
        ).trim()

      const metadata =
        getParticipantMetadata(participant)

      if (
        identity === expectedHostIdentity
      ) {
        return true
      }

      if (
        metadata.role === 'host' &&
        metadata.streamId === streamId
      ) {
        return true
      }

      if (
        participantMatchesUser(
          participant,
          broadcasterUserId,
        )
      ) {
        return true
      }

      return false
    }

    let host =
      participants.find(matches)

    if (
      !host &&
      room?.remoteParticipants
    ) {
      host =
        Array.from(
          room.remoteParticipants.values(),
        ).find(matches)
    }

    return host
  }

   useEffect(() => {
     const host = resolveBroadcasterParticipant(
       remoteParticipants,
       liveKitRoom,
       resolvedStreamId,
       hostId,
     )

    if (host) {
      hostParticipantRef.current =
        host

      updateBroadcasterState(
        host,
