  /* ========================================================================
     SEAT TRACKS
  ======================================================================== */

  const [
    seatTracks,
    setSeatTracks,
  ] =
    useState<
      Record<number, SeatState>
    >({})

  useEffect(() => {
    if (!liveKitRoom) {
      return
    }

    const syncSeats = () => {
      setSeatTracks(
        previous => {
          const next = {
            ...previous,
          }

          Object.entries(
            seats || {},
          ).forEach(
            ([
              index,
              seat,
            ]: [string, any]) => {
              const seatIndex =
                Number(index)

              const userId =
                seat?.user_id ||
                seat?.guest_id ||
                null

              const identity =
                seat?.livekit_participant_identity ||
                seat?.participant_identity ||
                seat?.livekit_identity ||
                userId

              if (
                !userId &&
                !identity
              ) {
                delete next[
                  seatIndex
                ]

                return
              }

              const participant =
                resolveSeatParticipant(
                  seat,
                  remoteParticipants,
                  liveKitRoom,
                )

              next[seatIndex] = {
                participant:
                  participant ||
                  null,

                videoTrack:
                  getVideoTrackFromParticipant(
                    participant,
                  ),

                audioTrack:
                  getAudioTrackFromParticipant(
                    participant,
                  ),

                isLoading:
                  Boolean(
                    seat?.status ===
                      'camera_starting',
                  ) &&
                  !participant,

                userId,
              }
            },
          )

          return next
        },
      )
    }

    syncSeats()

    liveKitRoom.on(
      RoomEvent.TrackSubscribed,
      syncSeats,
    )

    liveKitRoom.on(
      RoomEvent.TrackUnsubscribed,
      syncSeats,
    )

    liveKitRoom.on(
      RoomEvent.ParticipantConnected,
      syncSeats,
    )

    liveKitRoom.on(
      RoomEvent.ParticipantDisconnected,
      syncSeats,
    )

    return () => {
      liveKitRoom.off(
        RoomEvent.TrackSubscribed,
        syncSeats,
      )

      liveKitRoom.off(
        RoomEvent.TrackUnsubscribed,
        syncSeats,
      )

      liveKitRoom.off(
        RoomEvent.ParticipantConnected,
        syncSeats,
      )

      liveKitRoom.off(
        RoomEvent.ParticipantDisconnected,
        syncSeats,
      )
    }
  }, [
    liveKitRoom,
    remoteParticipants,
    seats,
  ])

  /* ========================================================================
      SEAT PUBLISH / UNPUBLISH
   ======================================================================== */

  const isUserOnStage = useMemo(() => {
    if (!mySeat || !user?.id) {
      return false
    }

    const status =
      String(mySeat?.status || '')
        .trim()
        .toLowerCase()

    return (
      [
        'reserved',
        'camera_starting',
        'active',
        'live',
      ].includes(status) &&
      (mySeat.user_id === user.id ||
        mySeat.guest_id === user.id)
    )
  }, [mySeat, user?.id])

  useEffect(() => {
    if (!liveKitRoom || !isConnected) {
      return
    }

    if (isUserOnStage && !isPublishing) {
      if (joiningPublisherRef.current || joiningAudienceRef.current) {
        return
      }

      joiningPublisherRef.current = true
      currentRoomKeyRef.current = `${resolvedStreamId}:${roomId}`

      void publishLocalTracks()
        .then(async () => {
          if (mySeat?.seat_index != null) {
            try {
              await markSeatLive(mySeat.seat_index, viewerIdentity)
            } catch (err) {
              console.warn('[PhoneViewerPage] markSeatLive after publish failed:', err)
            }
          }
        })
        .catch((err: any) => {
        })
        .finally(() => {
          joiningPublisherRef.current = false
        })
      return
    }

    if (!isUserOnStage && isPublishing) {
      joiningPublisherRef.current = true

      void unpublishLocalTracks()
        .catch((err: any) => {
        })
        .finally(() => {
          joiningPublisherRef.current = false
        })

      void leaveLiveKitRoom().catch(() => {})
      hasJoinedAudienceRef.current = false
      joiningAudienceRef.current = false
      currentRoomKeyRef.current = null
      return
    }
   }, [
     isUserOnStage,
     isConnected,
     isPublishing,
     liveKitRoom,
     publishLocalTracks,
     unpublishLocalTracks,
     leaveLiveKitRoom,
     resolvedStreamId,
     roomId,
     mySeat?.seat_index,
   ])

  const wasOnStageRef = useRef(isUserOnStage)

  useEffect(() => {
    if (wasOnStageRef.current) {
      wasOnStageRef.current = isUserOnStage
      return
    }
    wasOnStageRef.current = isUserOnStage
    if (!isUserOnStage) return

    joiningAudienceRef.current = false
    hasJoinedAudienceRef.current = false
    joiningAudienceRef.current = false
    audienceJoinAttemptedKeyRef.current = null
    currentRoomKeyRef.current = null

    // markSeatLive is called after publishLocalTracks() succeeds in this effect.
    void (async () => {
      joiningAudienceRef.current = true
      try {
