  /* ========================================================================
      SEAT CARDS
   ======================================================================== */

  const seatCards =
    useMemo<PhoneSeatCard[]>(
      () => {
        const configuredCount =
          Number(
            (stream as any)
              ?.seat_count ?? 0,
          )

        const priceCount =
          Array.isArray(
            (stream as any)
              ?.seat_prices,
          )
            ? (
                stream as any
              ).seat_prices.length
            : 0

        const count =
          Math.max(
            0,
            Math.min(
              6,
              configuredCount ||
                priceCount ||
                0,
            ),
          )

        const cards:
          PhoneSeatCard[] = []

        for (
          let index = 1;
          index <= count;
          index += 1
        ) {
          const seat =
            (seats as any)?.[
              index
            ] || null

          const status =
            String(
              seat?.status ||
                'empty',
            ).toLowerCase()

          const userId =
            seat?.user_id ||
            seat?.guest_id ||
            null

          const identity =
            seat?.livekit_participant_identity ||
            seat?.participant_identity ||
            seat?.livekit_identity ||
            userId

          const isOccupied =
            [
              'reserved',
              'camera_starting',
              'active',
              'live',
            ].includes(status) &&
            Boolean(userId)

          const isMine =
            Boolean(
              user?.id &&
              (
                seat?.user_id ===
                  user.id ||
                seat?.guest_id ===
                  user.id
              ),
            )

          const isLocked =
            Boolean(
              seat?.is_locked ||
              (
                stream as any
              )
                ?.are_seats_locked,
            )

          const amAlreadySeated =
            Boolean(
              mySeat &&
                [
                  'reserved',
                  'camera_starting',
                  'active',
                  'live',
                ].includes(
                  String(
                    mySeat.status ||
                      '',
                  ).toLowerCase(),
                ) &&
                (
                  mySeat.user_id ===
                    user?.id ||
                  mySeat.guest_id ===
                    user?.id
                ),
            )

          cards.push({
            seatIndex: index,
            seat,
            userId,
            identity,
            displayName:
              seat?.display_name ||
              seat?.username ||
              `Seat ${index}`,
            isOccupied,
            isMine,
            isLocked,
            canJoin:
              !isLocked &&
              !isOccupied &&
              !amAlreadySeated,
            seatPrice:
              getSeatPrice(
                stream,
                index,
              ),
          })
        }

        return cards
      },
      [
        seats,
        stream,
        user?.id,
        mySeat,
      ],
    )

  /* ========================================================================
     LIKES
  ======================================================================== */

  const pendingLikesRef =
    useRef(0)

  const flushInProgressRef =
    useRef(false)

  const clickTimesRef =
    useRef<number[]>([])

  const blockedUntilRef =
    useRef<number | null>(null)

  const flushLikes =
    useCallback(
      async () => {
        if (
          flushInProgressRef.current
        ) {
          return
        }

        const batch =
          pendingLikesRef.current

        if (
          batch <= 0 ||
          !resolvedStreamId
        ) {
          return
        }

        pendingLikesRef.current =
          0

        flushInProgressRef.current =
          true

        try {
          const {
            data,
            error,
          } =
             await supabase.rpc(
               'increment_stream_likes',
               {
                 p_stream_id:
                   resolvedStreamId,
                 p_like_count:
                   batch,
               },
             )

          if (error) {
            throw error
          }

          if (
            typeof data ===
            'number'
          ) {
            setStream(
              previous => {
                if (!previous) {
                  return previous
                }

                return {
                  ...previous,
                  total_likes:
                    data,
                }
              },
            )

             try {
               void sendStreamBroadcast(
                 resolvedStreamId,
                 'like_sent',
                 {
                   user_id:
                     user?.id,
                   stream_id:
                     resolvedStreamId,
                   total_likes:
                     data,
                },
              )
            } catch {
              // ignore
            }
          }
        } catch {
          pendingLikesRef.current +=
            batch
        } finally {
          flushInProgressRef.current =
            false
        }
      },
      [
        resolvedStreamId,
        user?.id,
      ],
    )

  useEffect(() => {
    const interval =
      window.setInterval(
        () => {
          void flushLikes()
        },
        2500,
      )

    const handleVisibilityChange =
      () => {
        if (
          document.visibilityState ===
          'hidden'
        ) {
          void flushLikes()
        }
      }

    document.addEventListener(
      'visibilitychange',
      handleVisibilityChange,
    )

    return () => {
      window.clearInterval(
        interval,
      )

      document.removeEventListener(
        'visibilitychange',
        handleVisibilityChange,
      )

      void flushLikes()
    }
  }, [flushLikes])

  const handleLike =
    useCallback(
      async () => {
        if (
          !resolvedStreamId ||
          !user?.id
        ) {
          navigate(
            '/auth?mode=signup',
          )

          return
        }

        const now =
          Date.now()

        if (
          blockedUntilRef.current &&
          now <
            blockedUntilRef.current
        ) {
          const secondsLeft =
            Math.ceil(
              (
                blockedUntilRef.current -
                now
              ) /
                1000,
            )

          toast.error(
            `You're temporarily blocked from liking (${secondsLeft}s)`,
          )

          return
        }

        const times =
          clickTimesRef.current

        times.push(now)

        const cutoff =
          now - 1000

        while (
          times.length &&
          times[0] <
            cutoff
        ) {
          times.shift()
        }

        if (
          times.length >=
          20
        ) {
          blockedUntilRef.current =
            now +
            60 *
              1000

          clickTimesRef.current =
            []

          toast.error(
            'Rate limited for 1 minute due to suspected auto-clicking',
          )

          return
        }

        setStream(
          previous =>
            previous
              ? {
                  ...previous,
                  total_likes:
                    Number(
                      previous.total_likes ||
                        0,
                    ) + 1,
                }
              : previous,
        )

        pendingLikesRef.current +=
          1

        if (
          pendingLikesRef.current >=
          25
        ) {
          void flushLikes()
        }
      },
      [
        resolvedStreamId,
        user?.id,
        flushLikes,
      ],
    )

  const lastTapRef =
    useRef(0)

  const handleBroadcasterTap =
    useCallback(() => {
      /*
       * Do not process broadcast double-tap likes
       * while the battle is covering the screen.
       */
      if (battleActive) {
        setShowControls(true)
        return
      }

      const now =
        Date.now()

      const difference =
        now -
        lastTapRef.current

      if (
        difference > 0 &&
        difference < 300
      ) {
        setLiked(true)

        window.setTimeout(
          () => {
            setLiked(false)
          },
          700,
        )

        void handleLike()
      }

      lastTapRef.current =
        now

      setShowControls(true)
    }, [
      battleActive,
      handleLike,
    ])

  const handleVideoTap =
    useCallback(
      (e: React.MouseEvent<HTMLDivElement>) => {
        const rect =
          e.currentTarget.getBoundingClientRect()

        const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
        const x =
          e.clientX -
          rect.left
        const y =
          e.clientY -
          rect.top

        setTapIndicators(
          previous => [
            ...previous,
            { id, x, y },
          ],
        )

        window.setTimeout(
          () => {
            setTapIndicators(
              previous =>
                previous.filter(
                  t => t.id !== id,
                ),
            )
          },
          900,
        )

        void handleLike()

        if (!showControls) {
          setShowControls(true)
        }
      },
      [
        handleLike,
        showControls,
      ],
    )

  /* ========================================================================
     SEATS
  ======================================================================== */

  const handleJoinSeat =
    useCallback(
      async (
        seatIndex: number,
      ) => {
        if (!joinSeat) {
          return
        }

        try {
          const price =
            getSeatPrice(
              stream,
              seatIndex,
            )

          await joinSeat(
            seatIndex,
            price,
            viewerIdentity,
          )
        } catch (err) {
          console.error(
            '[PhoneViewerPage] join seat failed',
            err,
          )
        }
      },
      [
        joinSeat,
        stream,
        viewerIdentity,
      ],
    )

  const handleLeaveSeat =
    useCallback(
      async () => {
        try {
          await leaveSeat?.()
        } catch (err) {
          console.error(
            '[PhoneViewerPage] leave seat failed',
            err,
          )
        }
      },
      [leaveSeat],
    )

  /* ========================================================================
     LEAVE
  ======================================================================== */

  const leave =
    useCallback(
      async () => {
        try {
          await leaveSeat?.()
        } catch {
          // ignore
        }

        try {
          await leaveAudience()
        } catch {
          // ignore
        }

        navigate(-1)
      },
      [
        leaveSeat,
        leaveAudience,
        navigate,
      ],
    )

  /* ========================================================================
     GIFTS
  ======================================================================== */

  const handleGift =
    useCallback(() => {
      if (!user) {
        navigate(
          '/auth?mode=signup',
        )

        return
      }

      setGiftRecipientId(
        hostId || null,
      )

      setIsGiftModalOpen(
        true,
      )
    }, [
      user,
      navigate,
      hostId,
    ])

  const handleOpenShareModal = useCallback(() => {
    setIsShareModalOpen(true)
  }, [])

  const handleInviteFollowers = useCallback(async () => {
    try {
      const { data: userData } = await supabase.auth.getUser()
      const inviterId = userData.user?.id
      if (!inviterId || !resolvedStreamId) return

      const { data, error } = await supabase.rpc('invite_followers_to_broadcast', {
        p_stream_id: resolvedStreamId,
        p_inviter_id: inviterId,
      })

      if (error) throw error
      toast.success(`Invited ${data.invited_count || 0} followers and following users`)
      void awardInvitePoint()
    } catch (inviteError: any) {
      toast.error(inviteError.message || 'Failed to send invites')
    }
  }, [resolvedStreamId])

  /* ========================================================================
     MIC / CAMERA
  ======================================================================== */

  const [
    micEnabled,
    setMicEnabledState,
  ] = useState(true)

  const [
    cameraEnabled,
    setCameraEnabledState,
  ] = useState(true)

  const handleMic =
    useCallback(
      async () => {
        const next =
          !micEnabled

        const ok =
          await setMicEnabled(
            next,
          )

        if (ok) {
          setMicEnabledState(
            next,
          )
        }
      },
      [
        micEnabled,
        setMicEnabled,
      ],
    )

  const handleCamera =
    useCallback(
      async () => {
        const next =
          !cameraEnabled

        const ok =
          await setCameraEnabled(
            next,
          )

        if (ok) {
          setCameraEnabledState(
            next,
          )
        }
      },
      [
        cameraEnabled,
        setCameraEnabled,
      ],
    )

  /* ========================================================================
     MODERATOR MUTE ENFORCEMENT
     ======================================================================== */

  const isModeratorMutedRef =
    useRef(false)

  const moderatorMuteTimestampRef =
    useRef(0)

  const moderatorMuteTimerRef =
    useRef<ReturnType<typeof setTimeout> | null>(null)

  const applyModeratorMute =
    useCallback(async () => {
      moderatorMuteTimestampRef.current = Date.now()
      isModeratorMutedRef.current = true

      if (moderatorMuteTimerRef.current) {
        clearTimeout(moderatorMuteTimerRef.current)
      }

      moderatorMuteTimerRef.current = setTimeout(() => {
        isModeratorMutedRef.current = false
        moderatorMuteTimestampRef.current = 0
        moderatorMuteTimerRef.current = null
        toast.info('You can now unmute your microphone')
      }, 5000)

      await setMicEnabled(false)
      setMicEnabledState(false)
    },
    [
      setMicEnabled,
      setMicEnabledState,
      toast,
    ],
    )

  const clearModeratorMute =
    useCallback(async () => {
      if (moderatorMuteTimerRef.current) {
        clearTimeout(moderatorMuteTimerRef.current)
      }

      moderatorMuteTimerRef.current = null
      moderatorMuteTimestampRef.current = 0
      isModeratorMutedRef.current = false

      await setMicEnabled(true)
      setMicEnabledState(true)
    },
    [
      setMicEnabled,
      setMicEnabledState,
    ],
    )

   useEffect(() => {
     if (!resolvedStreamId || !user?.id) return

     const checkMuteState = async () => {
       try {
         const { data } = await supabase
           .from('stream_mutes')
           .select('id, expires_at')
           .eq('stream_id', resolvedStreamId)
           .eq('user_id', user.id)
           .or(`expires_at.gt.${new Date().toISOString()},expires_at.is.null`)
           .maybeSingle()

         if (data) {
           toast.error('You have been muted by a moderator.')
           void applyModeratorMute()
         }
       } catch {
         // ignore
       }
     }

     void checkMuteState()

     const muteChannel = supabase
       .channel(`viewer-mute:${resolvedStreamId}:${user.id}`)
       .on(
         'postgres_changes',
         {
           event: 'INSERT',
           schema: 'public',
           table: 'stream_mutes',
           filter: `stream_id=eq.${resolvedStreamId}`,
         },
         (payload) => {
           const newMute = payload.new as any
           if (newMute?.user_id === user.id) {
             toast.error('You have been muted by a moderator.')
             void applyModeratorMute()
           }
         },
       )
       .on(
         'postgres_changes',
         {
           event: 'DELETE',
           schema: 'public',
           table: 'stream_mutes',
           filter: `stream_id=eq.${resolvedStreamId}`,
         },
         (payload) => {
           const oldMute = payload.old as any
           if (oldMute?.user_id === user.id) {
             toast.success('You have been unmuted.')
             void clearModeratorMute()
           }
         },
       )
       .subscribe()

     return () => {
       if (muteChannel) {
         supabase.removeChannel(muteChannel)
       }
     }
   }, [resolvedStreamId, user?.id, applyModeratorMute, clearModeratorMute])

