              recipientId={
                giftRecipientId ||
                hostId ||
                ''
              }
              streamId={
                streamId
              }
              broadcasterId={
                hostId
              }
            />
          </div>
        </GiftSystemProvider>
      </ErrorBoundary>
    );
  }

  /* ========================================================================
      MAIN VIEW
  ======================================================================== */

  return (
      <GiftSystemProvider
        streamId={resolvedStreamId}
        defaultReceiverId={
          stream.user_id
