      >
      <UndoRecentGiftBar />
      {isFeaturedEvent && (
        <FeaturedBanner
          broadcasters={featuredBroadcasters}
          event={featuredEvent}
          onOpenLeaderboard={openFeaturedLeaderboard}
        />
