      <FeaturedLiveOverlay active={!!currentStreamFeatured} className="left-4 top-4" />
      {!shouldShowRandomBattleArena && <FeaturedGiftBanner streamId={resolvedStreamId} broadcasterId={hostId} isMobile={true} />}
      <div
