          {/* Camera-off image fallback */}
          {!broadcasterState.videoTrack && (broadcasterProfile as any)?.camera_off_image_url && (
            <div className="pointer-events-none absolute inset-0 z-[1] h-full w-full overflow-hidden bg-black">
              <img
