        </div>

        {/* ================================================================
            FLOATING LIKE INDICATORS
        ================================================================= */}

        {!battleActive &&
          tapIndicators.length > 0 && (
            <div className="pointer-events-none absolute inset-0 z-[60] overflow-hidden">
              {tapIndicators.map(
